import json
import urllib.request
import base64

MCP_URL = "http://loophole-sim:8000/mcp"

class MCPClient:
    def __init__(self, url=MCP_URL):
        self.url = url
        self.session_id = None
        self.req_id = 0
        self._initialize()

    def _post(self, payload):
        data = json.dumps(payload).encode("utf-8")
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
        }
        if self.session_id:
            headers["mcp-session-id"] = self.session_id
        req = urllib.request.Request(self.url, data=data, headers=headers, method="POST")
        with urllib.request.urlopen(req, timeout=30) as resp:
            sid = resp.headers.get("mcp-session-id")
            if sid:
                self.session_id = sid
            ctype = resp.headers.get("Content-Type", "")
            raw = resp.read().decode("utf-8")
            if "text/event-stream" in ctype:
                # Parse SSE lines
                messages = []
                for line in raw.splitlines():
                    if line.startswith("data: "):
                        messages.append(json.loads(line[6:]))
                return messages[-1] if messages else None
            else:
                if not raw.strip():
                    return None
                return json.loads(raw)

    def _initialize(self):
        self.req_id += 1
        res = self._post({
            "jsonrpc": "2.0",
            "id": self.req_id,
            "method": "initialize",
            "params": {
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "clientInfo": {"name": "python-planner", "version": "1.0"}
            }
        })
        self._post({
            "jsonrpc": "2.0",
            "method": "notifications/initialized"
        })
        return res

    def call_tool(self, name, arguments=None):
        self.req_id += 1
        res = self._post({
            "jsonrpc": "2.0",
            "id": self.req_id,
            "method": "tools/call",
            "params": {
                "name": name,
                "arguments": arguments or {}
            }
        })
        if "error" in res:
            raise RuntimeError(f"MCP error: {res['error']}")
        return res["result"]

if __name__ == "__main__":
    client = MCPClient()
    state = client.call_tool("get_state")
    print("STATE:", json.dumps(state, indent=2))
    contacts = client.call_tool("get_contacts")
    print("CONTACTS:", json.dumps(contacts, indent=2))

