#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <random>
#include <chrono>
#include <cstring>
#include <omp.h>

struct Vec3 {
    float x, y, z;
    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
    Vec3 operator+(const Vec3& o) const { return Vec3(x + o.x, y + o.y, z + o.z); }
    Vec3 operator-(const Vec3& o) const { return Vec3(x - o.x, y - o.y, z - o.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    float dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return Vec3(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x);
    }
    float norm2() const { return x * x + y * y + z * z; }
    float norm() const { return std::sqrt(norm2()); }
};

struct Quat {
    float w, x, y, z;
    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}
    Quat normalized() const {
        float n = std::sqrt(w*w + x*x + y*y + z*z);
        if (n < 1e-12f) return Quat(1,0,0,0);
        if (w < 0) n = -n; // canonical hemisphere? Wait: keep sign careful for slerp!
        return Quat(w/n, x/n, y/n, z/n);
    }
    Quat unit() const {
        float n = std::sqrt(w*w + x*x + y*y + z*z);
        return (n > 1e-12f) ? Quat(w/n, x/n, y/n, z/n) : Quat(1,0,0,0);
    }
    Quat operator*(const Quat& o) const {
        return Quat(
            w*o.w - x*o.x - y*o.y - z*o.z,
            w*o.x + x*o.w + y*o.z - z*o.y,
            w*o.y - x*o.z + y*o.w + z*o.x,
            w*o.z + x*o.y - y*o.x + z*o.w
        );
    }
    Quat conj() const { return Quat(w, -x, -y, -z); }
    void toMat(float R[9]) const {
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;
        R[0] = 1.0f - 2.0f*(yy + zz); R[1] = 2.0f*(xy - wz);        R[2] = 2.0f*(xz + wy);
        R[3] = 2.0f*(xy + wz);        R[4] = 1.0f - 2.0f*(xx + zz); R[5] = 2.0f*(yz - wx);
        R[6] = 2.0f*(xz - wy);        R[7] = 2.0f*(yz + wx);        R[8] = 1.0f - 2.0f*(xx + yy);
    }
    static Quat fromAxisAngle(const Vec3& axis_angle) {
        float ang = axis_angle.norm();
        if (ang < 1e-8f) return Quat(1.0f, 0.5f*axis_angle.x, 0.5f*axis_angle.y, 0.5f*axis_angle.z).unit();
        float s = std::sin(0.5f * ang) / ang;
        return Quat(std::cos(0.5f * ang), axis_angle.x * s, axis_angle.y * s, axis_angle.z * s);
    }
};

static inline float quatAngleDist(const Quat& a, const Quat& b) {
    float d = std::abs(a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z);
    if (d > 1.0f) d = 1.0f;
    return 2.0f * std::acos(d);
}

static inline Quat quatSlerp(const Quat& a, Quat b, float t) {
    float d = a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z;
    if (d < 0.0f) { d = -d; b = Quat(-b.w, -b.x, -b.y, -b.z); }
    if (d > 0.9995f) {
        return Quat(a.w + t*(b.w - a.w), a.x + t*(b.x - a.x),
                    a.y + t*(b.y - a.y), a.z + t*(b.z - a.z)).unit();
    }
    float theta = std::acos(std::min(1.0f, d));
    float st = std::sin(theta);
    float wa = std::sin((1.0f - t)*theta) / st;
    float wb = std::sin(t*theta) / st;
    return Quat(wa*a.w + wb*b.w, wa*a.x + wb*b.x, wa*a.y + wb*b.y, wa*a.z + wb*b.z).unit();
}

struct Pose {
    Vec3 p;
    Quat q;
};

static inline Vec3 xform(const float R[9], const Vec3& t, const Vec3& v) {
    return Vec3(
        R[0]*v.x + R[1]*v.y + R[2]*v.z + t.x,
        R[3]*v.x + R[4]*v.y + R[5]*v.z + t.y,
        R[6]*v.x + R[7]*v.y + R[8]*v.z + t.z
    );
}

// Geometry globals
Vec3 pos_b0, out0_a, out1_a;
float max_r_l0;
std::vector<Vec3> surf_a, norm_a_in, cl_a;
std::vector<Vec3> pts_b_l0, pts_b_l1, pts_b_l2;

// 66-bucket hierarchy for tube_b
struct Bucket {
    Vec3 center;
    float r_max_coarse;
    float r_max_fine;
    std::vector<Vec3> coarse_pts;
    std::vector<Vec3> fine_pts;
};
std::vector<Bucket> buckets;

// 3D SDF grid of tube_a
struct SDFGrid {
    float xmin, ymin, zmin, h, inv_h;
    int nx, ny, nz;
    Vec3 bbox_min_surf, bbox_max_surf;
    std::vector<float> data;

    inline size_t idx(int i, int j, int k) const {
        return ((size_t)i * ny + j) * nz + k;
    }

    inline float query(const Vec3& p) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 0.0f || fy < 0.0f || fz < 0.0f || fx >= nx - 1.001f || fy >= ny - 1.001f || fz >= nz - 1.001f) {
            // Outside padded SDF grid: compute safe lower-bound distance to surf_a AABB!
            float dx = std::max({0.0f, bbox_min_surf.x - p.x, p.x - bbox_max_surf.x});
            float dy = std::max({0.0f, bbox_min_surf.y - p.y, p.y - bbox_max_surf.y});
            float dz = std::max({0.0f, bbox_min_surf.z - p.z, p.z - bbox_max_surf.z});
            return std::sqrt(dx*dx + dy*dy + dz*dz);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base];
        float c001 = data[base + 1];
        float c010 = data[base + sy];
        float c011 = data[base + sy + 1];
        float c100 = data[base + sx];
        float c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy];
        float c111 = data[base + sx + sy + 1];
        float c00 = c000 + tx*(c100 - c000);
        float c01 = c001 + tx*(c101 - c001);
        float c10 = c010 + tx*(c110 - c010);
        float c11 = c011 + tx*(c111 - c011);
        float c0 = c00 + ty*(c10 - c00);
        float c1 = c01 + ty*(c11 - c01);
        return c0 + tz*(c1 - c0);
    }

    inline float queryGrad(const Vec3& p, Vec3& grad) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 1.0f || fy < 1.0f || fz < 1.0f || fx >= nx - 2.001f || fy >= ny - 2.001f || fz >= nz - 2.001f) {
            grad = Vec3(0, 0, 0);
            return query(p);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base],          c001 = data[base + 1];
        float c010 = data[base + sy],     c011 = data[base + sy + 1];
        float c100 = data[base + sx],     c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy],c111 = data[base + sx + sy + 1];

        float d00 = c100 - c000, d01 = c101 - c001, d10 = c110 - c010, d11 = c111 - c011;
        float c00 = c000 + tx*d00, c01 = c001 + tx*d01, c10 = c010 + tx*d10, c11 = c011 + tx*d11;
        float c0 = c00 + ty*(c10 - c00), c1 = c01 + ty*(c11 - c01);
        float val = c0 + tz*(c1 - c0);

        float gx = ((1.0f - ty)*d00 + ty*d10)*(1.0f - tz) + ((1.0f - ty)*d01 + ty*d11)*tz;
        float gy = (c10 - c00)*(1.0f - tz) + (c11 - c01)*tz;
        float gz = c1 - c0;
        grad = Vec3(gx * inv_h, gy * inv_h, gz * inv_h);
        float gn = grad.norm();
        if (gn > 1e-6f) grad = grad * (1.0f / gn);
        return val;
    }
} sdf;

// 1D exact parabola lower envelope for continuous seeds (u_m, w_m) where u_m is sorted ascending!
// Minimizes (q - u_m)^2 + w_m for query coordinates q_i = q0 + i * h
void envelope1D(const std::vector<float>& u, const std::vector<float>& w, const std::vector<int>& id,
                float q0, float h, int n_out, std::vector<int>& out_id) {
    int m = (int)u.size();
    if (m == 0) {
        std::fill(out_id.begin(), out_id.end(), -1);
        return;
    }
    // Filter duplicate/very close u: keep minimum w
    std::vector<int> hull;
    std::vector<float> z(m + 1);
    hull.reserve(m);
    for (int i = 0; i < m; ++i) {
        if (!hull.empty() && std::abs(u[i] - u[hull.back()]) < 1e-6f) {
            if (w[i] < w[hull.back()]) {
                hull.back() = i;
                // recompute intersection with previous if needed
                while (hull.size() >= 2) {
                    int a = hull[hull.size() - 2];
                    int b = hull.back();
                    float inter = ((w[b] + u[b]*u[b]) - (w[a] + u[a]*u[a])) / (2.0f * (u[b] - u[a]));
                    if (hull.size() >= 3 && inter <= z[hull.size() - 2]) {
                        hull.erase(hull.end() - 2);
                    } else {
                        z[hull.size() - 1] = inter;
                        break;
                    }
                }
                if (hull.size() == 1) z[0] = -1e30f;
            }
            continue;
        }
        while (hull.size() >= 1) {
            int a = hull.back();
            float inter = ((w[i] + u[i]*u[i]) - (w[a] + u[a]*u[a])) / (2.0f * (u[i] - u[a]));
            if (hull.size() >= 2 && inter <= z[hull.size() - 1]) {
                hull.pop_back();
            } else {
                z[hull.size()] = inter;
                break;
            }
        }
        if (hull.empty()) z[0] = -1e30f;
        hull.push_back(i);
    }
    z[hull.size()] = 1e30f;
    int k = 0;
    int hs = (int)hull.size();
    for (int qi = 0; qi < n_out; ++qi) {
        float q = q0 + qi * h;
        while (k + 1 < hs && z[k + 1] < q) ++k;
        out_id[qi] = id[hull[k]];
    }
}

float distToCenterlineA(const Vec3& p) {
    float best2 = 1e30f;
    for (size_t i = 0; i + 1 < cl_a.size(); ++i) {
        Vec3 ab = cl_a[i+1] - cl_a[i];
        float len2 = ab.norm2();
        float t = (len2 > 1e-12f) ? (p - cl_a[i]).dot(ab) / len2 : 0.0f;
        t = std::max(0.0f, std::min(1.0f, t));
        Vec3 proj = cl_a[i] + ab * t;
        float d2 = (p - proj).norm2();
        if (d2 < best2) best2 = d2;
    }
    return std::sqrt(best2);
}

void buildSDF() {
    auto t0 = std::chrono::high_resolution_clock::now();
    Vec3 bmin(1e30f, 1e30f, 1e30f), bmax(-1e30f, -1e30f, -1e30f);
    for (const auto& p : surf_a) {
        bmin.x = std::min(bmin.x, p.x); bmin.y = std::min(bmin.y, p.y); bmin.z = std::min(bmin.z, p.z);
        bmax.x = std::max(bmax.x, p.x); bmax.y = std::max(bmax.y, p.y); bmax.z = std::max(bmax.z, p.z);
    }
    sdf.bbox_min_surf = bmin;
    sdf.bbox_max_surf = bmax;
    float pad = 0.20f;
    sdf.h = 0.004f;
    sdf.inv_h = 1.0f / sdf.h;
    sdf.xmin = bmin.x - pad;
    sdf.ymin = bmin.y - pad;
    sdf.zmin = bmin.z - pad;
    sdf.nx = (int)std::ceil((bmax.x + pad - sdf.xmin) * sdf.inv_h) + 1;
    sdf.ny = (int)std::ceil((bmax.y + pad - sdf.ymin) * sdf.inv_h) + 1;
    sdf.nz = (int)std::ceil((bmax.z + pad - sdf.zmin) * sdf.inv_h) + 1;
    size_t total = (size_t)sdf.nx * sdf.ny * sdf.nz;
    std::cout << "Building SDF grid: " << sdf.nx << " x " << sdf.ny << " x " << sdf.nz
              << " (" << (total * 4.0 / (1024*1024)) << " MB)..." << std::endl;

    std::vector<int> voronoi(total, -1);

    // Bin seeds into (j, k) rows first, sorted by x!
    std::vector<std::vector<int>> row_seeds((size_t)sdf.ny * sdf.nz);
    for (int idx = 0; idx < (int)surf_a.size(); ++idx) {
        int j = std::clamp((int)std::round((surf_a[idx].y - sdf.ymin) * sdf.inv_h), 0, sdf.ny - 1);
        int k = std::clamp((int)std::round((surf_a[idx].z - sdf.zmin) * sdf.inv_h), 0, sdf.nz - 1);
        row_seeds[(size_t)j * sdf.nz + k].push_back(idx);
    }

    // Pass 1: X
    #pragma omp parallel
    {
        std::vector<float> u, w;
        std::vector<int> ids, out(sdf.nx);
        #pragma omp for schedule(dynamic, 64)
        for (int jk = 0; jk < sdf.ny * sdf.nz; ++jk) {
            auto& seeds = row_seeds[jk];
            if (seeds.empty()) continue;
            std::sort(seeds.begin(), seeds.end(), [&](int a, int b){ return surf_a[a].x < surf_a[b].x; });
            int j = jk / sdf.nz, k = jk % sdf.nz;
            float y = sdf.ymin + j * sdf.h;
            float z = sdf.zmin + k * sdf.h;
            u.resize(seeds.size()); w.resize(seeds.size()); ids.resize(seeds.size());
            for (size_t s = 0; s < seeds.size(); ++s) {
                int id = seeds[s];
                u[s] = surf_a[id].x;
                float dy = y - surf_a[id].y, dz = z - surf_a[id].z;
                w[s] = dy*dy + dz*dz;
                ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.xmin, sdf.h, sdf.nx, out);
            for (int i = 0; i < sdf.nx; ++i) {
                voronoi[sdf.idx(i, j, k)] = out[i];
            }
        }
    }
    row_seeds.clear(); row_seeds.shrink_to_fit();

    // Pass 2: Y
    #pragma omp parallel
    {
        std::vector<int> cand;
        std::vector<float> u, w;
        std::vector<int> ids, out(sdf.ny);
        #pragma omp for schedule(dynamic, 64)
        for (int ik = 0; ik < sdf.nx * sdf.nz; ++ik) {
            int i = ik / sdf.nz, k = ik % sdf.nz;
            float x = sdf.xmin + i * sdf.h;
            float z = sdf.zmin + k * sdf.h;
            cand.clear();
            for (int j = 0; j < sdf.ny; ++j) {
                int id = voronoi[sdf.idx(i, j, k)];
                if (id >= 0) cand.push_back(id);
            }
            if (cand.empty()) continue;
            std::sort(cand.begin(), cand.end(), [&](int a, int b){ return surf_a[a].y < surf_a[b].y; });
            u.resize(cand.size()); w.resize(cand.size()); ids.resize(cand.size());
            for (size_t s = 0; s < cand.size(); ++s) {
                int id = cand[s];
                u[s] = surf_a[id].y;
                float dx = x - surf_a[id].x, dz = z - surf_a[id].z;
                w[s] = dx*dx + dz*dz;
                ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.ymin, sdf.h, sdf.ny, out);
            for (int j = 0; j < sdf.ny; ++j) {
                voronoi[sdf.idx(i, j, k)] = out[j];
            }
        }
    }

    // Pass 3: Z + compute signed distance!
    sdf.data.resize(total);
    #pragma omp parallel
    {
        std::vector<int> cand;
        std::vector<float> u, w;
        std::vector<int> ids, out(sdf.nz);
        #pragma omp for schedule(dynamic, 64)
        for (int ij = 0; ij < sdf.nx * sdf.ny; ++ij) {
            int i = ij / sdf.ny, j = ij % sdf.ny;
            float x = sdf.xmin + i * sdf.h;
            float y = sdf.ymin + j * sdf.h;
            cand.clear();
            for (int k = 0; k < sdf.nz; ++k) {
                int id = voronoi[sdf.idx(i, j, k)];
                if (id >= 0) cand.push_back(id);
            }
            u.resize(cand.size()); w.resize(cand.size()); ids.resize(cand.size());
            for (size_t s = 0; s < cand.size(); ++s) {
                int id = cand[s];
                u[s] = surf_a[id].z;
                float dx = x - surf_a[id].x, dy = y - surf_a[id].y;
                w[s] = dx*dx + dy*dy;
                ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.zmin, sdf.h, sdf.nz, out);
            for (int k = 0; k < sdf.nz; ++k) {
                int id = out[k];
                float z = sdf.zmin + k * sdf.h;
                Vec3 g(x, y, z);
                Vec3 diff = g - surf_a[id];
                float d = diff.norm();
                float sign = 1.0f;
                if (d < 0.12f) {
                    float dot_in = diff.dot(norm_a_in[id]);
                    if (dot_in > 0.0002f) {
                        // Also verify inside tube envelope
                        if ((g - cl_a.front()).dot(out0_a) <= 0.002f &&
                            (g - cl_a.back()).dot(out1_a) <= 0.002f &&
                            distToCenterlineA(g) < 0.110f) {
                            sign = -1.0f;
                        }
                    }
                }
                sdf.data[sdf.idx(i, j, k)] = sign * d;
            }
        }
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    std::cout << "SDF built in " << std::chrono::duration<double>(t1 - t0).count() << " s." << std::endl;
}

// Fast clearance / collision check!
// Returns minimum SDF if >= threshold, else returns early value < threshold!
float checkClearance(const Pose& pose, float threshold, bool fine = true) {
    // Workspace check on handle (reference point pose.p):
    // Workspace is [-0.8, 3.2]^3; keep comfortable margin [-0.72, 3.12]^3
    if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
        pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) {
        return -1.0f;
    }
    float R[9];
    pose.q.toMat(R);

    float min_d = 1e30f;
    float d_centers[66];

    // Pass 0: check 66 centerline points!
    for (int b = 0; b < 66; ++b) {
        Vec3 wc = xform(R, pose.p, buckets[b].center);
        float d = sdf.query(wc);
        d_centers[b] = d;
        // On interior buckets (2..63), tube cross section has radius >= 0.102m in all directions around center!
        if (b >= 2 && b <= 63 && d < 0.096f + threshold) {
            return d - 0.103f; // Guaranteed < threshold!
        }
        // Lower bound on this bucket is d - r_max_fine
        if (d - buckets[b].r_max_fine < min_d) {
            // Will need bucket check if d <= r_max_fine + threshold (or if computing exact min_d)
        } else {
            // Even without checking points, this bucket is >= min_d
        }
    }

    // Pass 1: for any bucket where d_centers[b] <= r_max_fine + threshold (or to get accurate min_d < 0.06f)
    float active_band = std::max(threshold, 0.05f);
    bool any_active = false;
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + active_band) {
            any_active = true;
            for (const auto& pt : buckets[b].coarse_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        } else {
            float lb = d_centers[b] - buckets[b].r_max_fine;
            if (lb < min_d) min_d = lb;
        }
    }
    if (!fine || !any_active) return min_d;

    // Pass 2: fine check only on buckets where d_centers[b] <= r_max_fine + std::min(min_d, active_band)
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + std::max(threshold + 0.008f, std::min(min_d, 0.035f))) {
            for (const auto& pt : buckets[b].fine_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        }
    }
    return min_d;
}

// Retract/push a pose away from tube_a using SDF gradients!
// Pushes any surface points closer than target_margin outward!
bool retractPose(Pose& pose, float target_margin, int max_iters = 6) {
    for (int it = 0; it < max_iters; ++it) {
        if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
            pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) {
            return false;
        }
        float R[9];
        pose.q.toMat(R);
        Vec3 F(0,0,0), tau(0,0,0);
        float min_d = 1e30f;
        int n_act = 0;
        float sense = target_margin + 0.012f;

        for (int b = 0; b < 66; ++b) {
            Vec3 wc = xform(R, pose.p, buckets[b].center);
            float dc = sdf.query(wc);
            if (dc > buckets[b].r_max_coarse + sense) {
                min_d = std::min(min_d, dc - buckets[b].r_max_coarse);
                continue;
            }
            for (const auto& pt : buckets[b].coarse_pts) {
                Vec3 rel(R[0]*pt.x + R[1]*pt.y + R[2]*pt.z,
                         R[3]*pt.x + R[4]*pt.y + R[5]*pt.z,
                         R[6]*pt.x + R[7]*pt.y + R[8]*pt.z);
                Vec3 wp = pose.p + rel;
                Vec3 g;
                float d = sdf.queryGrad(wp, g);
                if (d < min_d) min_d = d;
                if (d < sense && g.norm2() > 0.5f) {
                    float w = (sense - d);
                    F = F + g * w;
                    tau = tau + rel.cross(g * w);
                    n_act++;
                }
            }
        }
        if (min_d >= target_margin) {
            // Double check with fine points!
            if (checkClearance(pose, target_margin, true) >= target_margin) return true;
        }
        if (n_act == 0) break;
        F = F * (1.0f / n_act);
        tau = tau * (1.0f / n_act);
        float fn = F.norm();
        float tn = tau.norm();
        float step_need = std::max(0.004f, std::min(0.035f, (target_margin - min_d) + 0.004f));
        if (fn > 1e-6f || tn > 1e-6f) {
            // Combine linear and rotational push (characteristic radius ~ 0.6m)
            float denom = fn*fn + 0.35f * tn*tn + 1e-9f;
            float alpha = step_need / std::sqrt(denom);
            Vec3 dp = F * alpha;
            Vec3 dw = tau * (0.35f * alpha);
            if (dp.norm() > 0.035f) dp = dp * (0.035f / dp.norm());
            if (dw.norm() > 0.07f)  dw = dw * (0.07f / dw.norm());
            pose.p = pose.p + dp;
            pose.q = (Quat::fromAxisAngle(dw) * pose.q).unit();
        } else {
            break;
        }
    }
    return checkClearance(pose, target_margin, true) >= target_margin;
}

// Check continuous edge validity between p0 and p1
bool edgeValid(const Pose& a, const Pose& b, float margin, bool check_both_profiles = false) {
    float dp = (b.p - a.p).norm();
    float dq = quatAngleDist(a.q, b.q);
    int steps = std::max(2, (int)std::ceil(std::max(dp / 0.012f, dq / 0.015f)));
    for (int s = 1; s <= steps; ++s) {
        float t = (float)s / steps;
        Pose m;
        m.p = a.p + (b.p - a.p) * t;
        m.q = quatSlerp(a.q, b.q, t);
        if (checkClearance(m, margin, true) < margin) return false;
    }
    if (check_both_profiles && (dp > 1e-5f && dq > 1e-5f)) {
        // Also check independent speed limiter profile (v=0.1 m/s, w=0.1 rad/s)!
        float t_lin = dp / 0.1f;
        float t_ang = dq / 0.1f;
        float t_tot = std::max(t_lin, t_ang);
        for (int s = 1; s < steps; ++s) {
            float tau = ((float)s / steps) * t_tot;
            float sl = std::min(1.0f, tau / t_lin);
            float sa = std::min(1.0f, tau / t_ang);
            if (std::abs(sl - sa) < 0.02f) continue;
            Pose m;
            m.p = a.p + (b.p - a.p) * sl;
            m.q = quatSlerp(a.q, b.q, sa);
            if (checkClearance(m, margin, true) < margin) return false;
        }
    }
    return true;
}

// Check if from `pose`, tube_b can translate along SOME straight-line ray u in S^2 to infinity with clearance >= ray_margin!
bool canEscapeAlongRay(const Pose& pose, float ray_margin, Vec3* best_dir = nullptr) {
    if (checkClearance(pose, ray_margin, true) < ray_margin) return false;
    // Generate 162 Fibonacci directions on S^2
    static std::vector<Vec3> dirs;
    if (dirs.empty()) {
        const int N = 162;
        const float golden = 3.14159265359f * (3.0f - std::sqrt(5.0f));
        for (int i = 0; i < N; ++i) {
            float y = 1.0f - (2.0f * i) / (N - 1);
            float r = std::sqrt(std::max(0.0f, 1.0f - y*y));
            float th = golden * i;
            dirs.emplace_back(std::cos(th)*r, y, std::sin(th)*r);
        }
    }
    float best_min_c = -1.0f;
    Vec3 best_u(1,0,0);
    for (const auto& u : dirs) {
        bool ok = true;
        float min_c = 1e30f;
        // March t from 0.02m up to 3.8m (beyond 3.8m, the 2.5m tubes are completely disjoint!)
        for (float t = 0.025f; t <= 3.8f; t += 0.025f) {
            Pose shifted = pose;
            shifted.p = pose.p + u * t;
            // Note: escape ray goes to infinity, so ignore workspace box in checkClearance!
            float R[9];
            shifted.q.toMat(R);
            // Quick AABB check if completely outside sdf box + 0.1m
            float d_min_step = 1e30f;
            for (int b = 0; b < 66; ++b) {
                Vec3 wc = xform(R, shifted.p, buckets[b].center);
                float dc = sdf.query(wc);
                if (b >= 2 && b <= 63 && dc < 0.096f + ray_margin) { ok = false; break; }
                if (dc <= buckets[b].r_max_fine + ray_margin + 0.01f) {
                    for (const auto& pt : buckets[b].coarse_pts) {
                        float d = sdf.query(xform(R, shifted.p, pt));
                        if (d < ray_margin) { ok = false; break; }
                        d_min_step = std::min(d_min_step, d);
                    }
                    if (!ok) break;
                    for (const auto& pt : buckets[b].fine_pts) {
                        float d = sdf.query(xform(R, shifted.p, pt));
                        if (d < ray_margin) { ok = false; break; }
                        d_min_step = std::min(d_min_step, d);
                    }
                    if (!ok) break;
                } else {
                    d_min_step = std::min(d_min_step, dc - buckets[b].r_max_fine);
                }
            }
            if (!ok) break;
            min_c = std::min(min_c, d_min_step);
        }
        if (ok) {
            if (best_dir == nullptr) return true;
            if (min_c > best_min_c) {
                best_min_c = min_c;
                best_u = u;
            }
        }
    }
    if (best_min_c >= ray_margin) {
        if (best_dir) *best_dir = best_u;
        return true;
    }
    return false;
}

struct Node {
    Pose pose;
    int parent;
};

float poseMetric(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.65f * quatAngleDist(a.q, b.q);
}

int nearestNode(const std::vector<Node>& tree, const Pose& target) {
    int best = 0;
    float best_d = 1e30f;
    int n = (int)tree.size();
    #pragma omp parallel if(n > 1500)
    {
        int lb = 0;
        float ld = 1e30f;
        #pragma omp for nowait
        for (int i = 0; i < n; ++i) {
            float d = poseMetric(tree[i].pose, target);
            if (d < ld) { ld = d; lb = i; }
        }
        #pragma omp critical
        {
            if (ld < best_d) { best_d = ld; best = lb; }
        }
    }
    return best;
}

enum GrowStatus { TRAPPED, ADVANCED, REACHED };

// Sliding / Retracted RRT step!
GrowStatus extendSliding(std::vector<Node>& tree, const Pose& target, float margin, int& out_idx) {
    int near_id = nearestNode(tree, target);
    const Pose& cur = tree[near_id].pose;
    Vec3 dp = target.p - cur.p;
    float lp = dp.norm();
    float lq = quatAngleDist(cur.q, target.q);

    const float max_dp = 0.065f;
    const float max_dq = 0.11f;
    float frac = 1.0f;
    if (lp > max_dp) frac = std::min(frac, max_dp / lp);
    if (lq > max_dq) frac = std::min(frac, max_dq / lq);

    Pose cand;
    cand.p = cur.p + dp * frac;
    cand.q = quatSlerp(cur.q, target.q, frac);

    bool ok = (checkClearance(cand, margin, true) >= margin);
    if (!ok) {
        // Try sliding / retracting along SDF gradient!
        Pose slid = cand;
        if (retractPose(slid, margin + 0.002f, 5)) {
            // Make sure we actually made forward progress and didn't just bounce back to cur!
            if (poseMetric(slid, cur) > 0.012f && poseMetric(slid, target) < poseMetric(cur, target) - 0.003f) {
                cand = slid;
                ok = true;
            }
        }
    }
    if (!ok) return TRAPPED;
    if (!edgeValid(cur, cand, margin, false)) return TRAPPED;

    out_idx = (int)tree.size();
    tree.push_back({cand, near_id});
    return (frac >= 0.999f && poseMetric(cand, target) < 0.01f) ? REACHED : ADVANCED;
}

GrowStatus connectSliding(std::vector<Node>& tree, const Pose& target, float margin, int& last_idx) {
    last_idx = -1;
    for (int steps = 0; steps < 80; ++steps) {
        int new_id = -1;
        GrowStatus st = extendSliding(tree, target, margin, new_id);
        if (st == TRAPPED) return (steps == 0) ? TRAPPED : ADVANCED;
        last_idx = new_id;
        if (st == REACHED) return REACHED;
        if (poseMetric(tree[new_id].pose, target) < 0.08f) {
            if (edgeValid(tree[new_id].pose, target, margin, false)) {
                int fin_id = (int)tree.size();
                tree.push_back({target, new_id});
                last_idx = fin_id;
                return REACHED;
            }
        }
    }
    return ADVANCED;
}

int main(int argc, char** argv) {
    float plan_margin = (argc > 1) ? std::atof(argv[1]) : 0.008f; // default 8 mm
    std::ifstream f("/app/geometry.bin", std::ios::binary);
    if (!f) { std::cerr << "Cannot open geometry.bin\n"; return 1; }
    auto readVec3s = [&](std::vector<Vec3>& v) {
        uint32_t n = 0;
        f.read((char*)&n, 4);
        v.resize(n);
        f.read((char*)v.data(), n * sizeof(Vec3));
    };
    f.read((char*)&pos_b0, sizeof(Vec3));
    f.read((char*)&max_r_l0, 4);
    f.read((char*)&out0_a, sizeof(Vec3));
    f.read((char*)&out1_a, sizeof(Vec3));
    readVec3s(surf_a);
    readVec3s(norm_a_in);
    readVec3s(cl_a);
    readVec3s(pts_b_l0);
    readVec3s(pts_b_l1);
    readVec3s(pts_b_l2);
    std::cout << "Loaded geometry: surf_a=" << surf_a.size()
              << ", b_l0=" << pts_b_l0.size() << ", b_l1=" << pts_b_l1.size()
              << ", b_l2=" << pts_b_l2.size() << std::endl;

    // Build 66 buckets for tube_b
    buckets.resize(66);
    for (int b = 0; b < 66; ++b) {
        buckets[b].center = pts_b_l0[b];
        buckets[b].r_max_coarse = 0.0f;
        buckets[b].r_max_fine = 0.0f;
    }
    auto assignBucket = [&](const Vec3& p) {
        int best = 0; float bd = 1e30f;
        for (int b = 0; b < 66; ++b) {
            float d2 = (p - buckets[b].center).norm2();
            if (d2 < bd) { bd = d2; best = b; }
        }
        return best;
    };
    // Subsample pts_b_l1 by ~4x for ultra-fast coarse check (~1800 pts total, ~27 per bucket), keep all pts_b_l2 in fine!
    for (size_t i = 0; i < pts_b_l1.size(); i += 3) {
        int b = assignBucket(pts_b_l1[i]);
        buckets[b].coarse_pts.push_back(pts_b_l1[i]);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, (pts_b_l1[i] - buckets[b].center).norm());
    }
    // Also ensure every bucket has at least some coarse pts, and refine using pts_b_l1 + subsample of pts_b_l2 (~18,000 fine pts)
    for (size_t i = 0; i < pts_b_l2.size(); i += 3) {
        int b = assignBucket(pts_b_l2[i]);
        buckets[b].fine_pts.push_back(pts_b_l2[i]);
        float r = (pts_b_l2[i] - buckets[b].center).norm();
        buckets[b].r_max_fine = std::max(buckets[b].r_max_fine, r);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, r);
    }

    buildSDF();

    Pose start_pose{pos_b0, Quat(1,0,0,0)};
    float c0 = checkClearance(start_pose, -1.0f, true);
    std::cout << "Start pose SDF clearance: " << c0 << " m (canEscape=" << canEscapeAlongRay(start_pose, 0.005f) << ")" << std::endl;

    // Benchmark checkClearance speed!
    std::mt19937 rng(12345);
    std::uniform_real_distribution<float> ux(-0.4f, 2.7f), uy(-0.4f, 2.0f), uz(-0.4f, 1.0f), u01(0.0f, 1.0f);
    auto randQuat = [&]() {
        float u1 = u01(rng), u2 = u01(rng)*6.2831853f, u3 = u01(rng)*6.2831853f;
        float s1 = std::sqrt(1.0f - u1), s2 = std::sqrt(u1);
        return Quat(s1*std::sin(u2), s1*std::cos(u2), s2*std::sin(u3), s2*std::cos(u3)).unit();
    };

    // Bidirectional Sliding RRT-Connect!
    std::vector<Node> tA, tB;
    tA.push_back({start_pose, -1});

    // Seed goal tree tB with several escaped poses around tube_a inside workspace!
    std::vector<Vec3> goal_positions = {
        Vec3(2.4f, -0.3f, 0.5f), Vec3(-0.3f, 1.5f, 0.5f),
        Vec3(1.2f, 2.2f, 0.5f),  Vec3(1.2f, -0.5f, 0.8f),
        Vec3(1.0f, 0.6f, 1.3f),  Vec3(2.5f, 1.5f, 0.8f)
    };
    // Connect goal roots to a single virtual root (index 0) so all goal seeds work together!
    Pose rootB{Vec3(1.2f, 0.6f, 1.6f), Quat(1,0,0,0)};
    tB.push_back({rootB, -1});
    for (const auto& gp : goal_positions) {
        Pose p{gp, Quat(1,0,0,0)};
        if (checkClearance(p, 0.05f, true) >= 0.05f && edgeValid(rootB, p, 0.03f, false)) {
            tB.push_back({p, 0});
        }
    }
    std::cout << "Planning with margin = " << plan_margin << " m, goal seeds = " << tB.size() << "..." << std::endl;

    auto tp0 = std::chrono::high_resolution_clock::now();
    int sol_a = -1, sol_b = -1;
    bool swapped = false;

    for (int iter = 1; iter <= 150000; ++iter) {
        Pose q_rand;
        float mode = u01(rng);
        if (mode < 0.45f) {
            // Sample near puzzle interaction zone + retract if colliding (OBPRM narrow-passage bias!)
            q_rand.p = Vec3(ux(rng), uy(rng), uz(rng));
            q_rand.q = randQuat();
            float c = checkClearance(q_rand, plan_margin, false);
            if (c < plan_margin && c > -0.06f) {
                retractPose(q_rand, plan_margin + 0.003f, 6);
            }
        } else if (mode < 0.75f) {
            // Perturb an existing node of tA (especially frontier/distant nodes) to explore narrow tunnels!
            const auto& base = (!swapped ? tA : tB)[rng() % (!swapped ? tA.size() : tB.size())].pose;
            std::normal_distribution<float> gp(0.0f, 0.25f), gq(0.0f, 0.45f);
            q_rand.p = base.p + Vec3(gp(rng), gp(rng), gp(rng));
            q_rand.q = (Quat::fromAxisAngle(Vec3(gq(rng), gq(rng), gq(rng))) * base.q).unit();
            retractPose(q_rand, plan_margin + 0.003f, 5);
        } else {
            // Wide workspace uniform
            std::uniform_real_distribution<float> wx(-0.5f, 2.8f), wy(-0.5f, 2.4f), wz(-0.5f, 1.7f);
            q_rand.p = Vec3(wx(rng), wy(rng), wz(rng));
            q_rand.q = randQuat();
        }

        auto& tree1 = !swapped ? tA : tB;
        auto& tree2 = !swapped ? tB : tA;

        int new1 = -1;
        if (extendSliding(tree1, q_rand, plan_margin, new1) != TRAPPED) {
            // First check if new1 in tA can ALREADY escape along a straight ray!
            if (!swapped && iter % 3 == 0) {
                // Quick check: if far enough from start, test ray escape!
                if (poseMetric(tree1[new1].pose, start_pose) > 0.7f &&
                    canEscapeAlongRay(tree1[new1].pose, plan_margin + 0.006f)) {
                    sol_a = new1;
                    sol_b = -2; // direct ray escape!
                    std::cout << "Direct ray-escape solution found at iter " << iter
                              << "! |tA|=" << tA.size() << ", |tB|=" << tB.size() << std::endl;
                    break;
                }
            }
            int new2 = -1;
            if (connectSliding(tree2, tree1[new1].pose, plan_margin, new2) == REACHED) {
                sol_a = !swapped ? new1 : new2;
                sol_b = !swapped ? new2 : new1;
                std::cout << "Trees connected at iter " << iter
                          << "! |tA|=" << tA.size() << ", |tB|=" << tB.size() << std::endl;
                break;
            }
        }
        swapped = !swapped;

        if (iter % 5000 == 0) {
            double el = std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - tp0).count();
            // Compute max displacement in tA from start
            float max_d = 0.0f;
            for (const auto& n : tA) max_d = std::max(max_d, poseMetric(n.pose, start_pose));
            std::cout << "Iter " << iter << " (" << el << " s): |tA|=" << tA.size()
                      << ", |tB|=" << tB.size() << ", max_dist_from_start=" << max_d << std::endl;
        }
    }

    if (sol_a < 0) {
        std::cout << "Failed to find path within iteration limit." << std::endl;
        return 2;
    }

    // Reconstruct raw path from start
    std::vector<Pose> path;
    for (int cur = sol_a; cur != -1; cur = tA[cur].parent) path.push_back(tA[cur].pose);
    std::reverse(path.begin(), path.end());
    if (sol_b >= 0) {
        for (int cur = tB[sol_b].parent; cur != -1; cur = tB[cur].parent) path.push_back(tB[cur].pose);
    }
    std::cout << "Raw path waypoints: " << path.size() << std::endl;

    // Truncate at earliest waypoint with generous ray escape (margin >= 0.020m), plus 1 extra step of 0.08m along best escape ray!
    int cut_idx = (int)path.size() - 1;
    Vec3 esc_dir(0,0,1);
    for (int i = 1; i < (int)path.size(); ++i) {
        Vec3 u;
        if (canEscapeAlongRay(path[i], 0.020f, &u)) {
            cut_idx = i;
            esc_dir = u;
            std::cout << "Earliest clean ray-escape at waypoint " << i << " / " << path.size()
                      << " along dir (" << u.x << ", " << u.y << ", " << u.z << ")!" << std::endl;
            break;
        }
    }
    path.resize(cut_idx + 1);
    // Add one small 0.08m step along esc_dir (if inside workspace) just to be comfortably clear!
    Pose bonus = path.back();
    bonus.p = bonus.p + esc_dir * 0.08f;
    if (edgeValid(path.back(), bonus, plan_margin, true) && canEscapeAlongRay(bonus, 0.025f)) {
        path.push_back(bonus);
    }

    // Clearance-boosting + shortcutting!
    // First subdivide into fine steps (~0.03m / 0.05rad) so we can boost clearance & shortcut cleanly
    auto subdivide = [&](const std::vector<Pose>& in, float max_p, float max_q) {
        std::vector<Pose> out;
        out.push_back(in[0]);
        for (size_t i = 0; i + 1 < in.size(); ++i) {
            float dp = (in[i+1].p - in[i].p).norm();
            float dq = quatAngleDist(in[i].q, in[i+1].q);
            int k = std::max(1, (int)std::ceil(std::max(dp / max_p, dq / max_q)));
            for (int s = 1; s <= k; ++s) {
                float t = (float)s / k;
                Pose m{in[i].p + (in[i+1].p - in[i].p)*t, quatSlerp(in[i].q, in[i+1].q, t)};
                out.push_back(m);
            }
        }
        return out;
    };

    path = subdivide(path, 0.035f, 0.06f);

    // Shortcut in action-cost metric!
    std::mt19937 srng(999);
    for (int sc = 0; sc < 1500 && path.size() > 3; ++sc) {
        int i = srng() % (path.size() - 2);
        int j = i + 2 + (srng() % (path.size() - i - 2));
        if (edgeValid(path[i], path[j], plan_margin + 0.002f, true)) {
            // Replace [i..j] with subdivided straight segment
            std::vector<Pose> seg = subdivide({path[i], path[j]}, 0.035f, 0.06f);
            std::vector<Pose> next;
            next.insert(next.end(), path.begin(), path.begin() + i);
            next.insert(next.end(), seg.begin(), seg.end());
            next.insert(next.end(), path.begin() + j + 1, path.end());
            path.swap(next);
        }
    }

    // Boost clearance on interior waypoints!
    for (int pass = 0; pass < 4; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            Pose cand = path[i];
            // Average with neighbors smoothly + push away from walls up to 0.018m
            cand.p = (path[i-1].p + path[i].p * 2.0f + path[i+1].p) * 0.25f;
            cand.q = quatSlerp(quatSlerp(path[i-1].q, path[i+1].q, 0.5f), path[i].q, 0.5f);
            if (retractPose(cand, std::max(plan_margin + 0.006f, 0.016f), 2) ||
                checkClearance(cand, plan_margin + 0.002f, true) >= plan_margin + 0.002f) {
                if (edgeValid(path[i-1], cand, plan_margin + 0.001f, true) &&
                    edgeValid(cand, path[i+1], plan_margin + 0.001f, true)) {
                    path[i] = cand;
                }
            }
        }
    }

    // Greedy conversion into minimum number of legal `move` steps (||dp|| <= 0.096 m, ||dq|| <= 0.192 rad)
    // checking BOTH synchronized and independent rate-limiter profiles!
    std::vector<Pose> actions;
    actions.push_back(path[0]);
    size_t cur_i = 0;
    while (cur_i + 1 < path.size()) {
        size_t best_j = cur_i + 1;
        // Also allow interpolating inside segment [j, j+1] for maximum step utilization!
        Pose best_pose = path[cur_i + 1];
        for (size_t j = cur_i + 1; j < path.size(); ++j) {
            float dp = (path[j].p - actions.back().p).norm();
            float dq = quatAngleDist(actions.back().q, path[j].q);
            if (dp <= 0.096f && dq <= 0.192f) {
                if (edgeValid(actions.back(), path[j], plan_margin, true)) {
                    best_j = j;
                    best_pose = path[j];
                }
            } else {
                // Binary search fractional point on [path[j-1], path[j]] if j == best_j + 1
                break;
            }
        }
        // If best_j == cur_i + 1 and step exceeds limit (unlikely since subdivided to 0.035/0.06), subdivide
        float dp = (best_pose.p - actions.back().p).norm();
        float dq = quatAngleDist(actions.back().q, best_pose.q);
        if (dp > 0.096f || dq > 0.192f) {
            float f = std::min(0.096f / std::max(dp, 1e-6f), 0.192f / std::max(dq, 1e-6f));
            best_pose.p = actions.back().p + (best_pose.p - actions.back().p) * f;
            best_pose.q = quatSlerp(actions.back().q, best_pose.q, f);
            actions.push_back(best_pose);
        } else {
            actions.push_back(best_pose);
            cur_i = best_j;
        }
    }

    // Check minimum clearance across ALL dense substeps of final action sequence!
    float min_path_c = 1e30f;
    for (size_t i = 0; i + 1 < actions.size(); ++i) {
        for (int s = 0; s <= 25; ++s) {
            float t = (float)s / 25.0f;
            Pose m{actions[i].p + (actions[i+1].p - actions[i].p)*t, quatSlerp(actions[i].q, actions[i+1].q, t)};
            min_path_c = std::min(min_path_c, checkClearance(m, -1.0f, true));
        }
    }

    std::cout << "=== FINAL ACTION PLAN ===" << std::endl;
    std::cout << "Move steps: " << (actions.size() - 1) << " (+1 grab = " << actions.size() << " total actions)" << std::endl;
    std::cout << "Minimum SDF clearance along entire trajectory: " << min_path_c << " m" << std::endl;
    Vec3 final_esc;
    bool fin_ok = canEscapeAlongRay(actions.back(), 0.020f, &final_esc);
    std::cout << "Final pose escape check (20mm margin): " << fin_ok
              << " dir=(" << final_esc.x << "," << final_esc.y << "," << final_esc.z << ")" << std::endl;

    std::ofstream out("/app/planned_path.txt");
    out.precision(8);
    for (const auto& a : actions) {
        out << a.p.x << " " << a.p.y << " " << a.p.z << " "
            << a.q.w << " " << a.q.x << " " << a.q.y << " " << a.q.z << "\n";
    }
    std::cout << "Saved /app/planned_path.txt" << std::endl;
    return 0;
}

