struct SDFGrid {
    float xmin, ymin, zmin, h, inv_h;
    int nx, ny, nz;
    Vec3 bbox_min_surf, bbox_max_surf;
    std::vector<float> data;

    inline size_t idx(int i, int j, int k) const {
        return ((size_t)i * ny + j) * nz + k;
    }

    inline float query(const Vec3& p) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 0.0f || fy < 0.0f || fz < 0.0f || fx >= nx - 1.001f || fy >= ny - 1.001f || fz >= nz - 1.001f) {
            float dx = std::max({0.0f, bbox_min_surf.x - p.x, p.x - bbox_max_surf.x});
            float dy = std::max({0.0f, bbox_min_surf.y - p.y, p.y - bbox_max_surf.y});
            float dz = std::max({0.0f, bbox_min_surf.z - p.z, p.z - bbox_max_surf.z});
            return std::sqrt(dx*dx + dy*dy + dz*dz);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base],          c001 = data[base + 1];
        float c010 = data[base + sy],     c011 = data[base + sy + 1];
        float c100 = data[base + sx],     c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy],c111 = data[base + sx + sy + 1];
        float c00 = c000 + tx*(c100 - c000), c01 = c001 + tx*(c101 - c001);
        float c10 = c010 + tx*(c110 - c010), c11 = c011 + tx*(c111 - c011);
        float c0 = c00 + ty*(c10 - c00),     c1 = c01 + ty*(c11 - c01);
        return c0 + tz*(c1 - c0);
    }

    inline float queryGrad(const Vec3& p, Vec3& grad) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 1.0f || fy < 1.0f || fz < 1.0f || fx >= nx - 2.001f || fy >= ny - 2.001f || fz >= nz - 2.001f) {
            grad = Vec3(0, 0, 0);
            return query(p);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base],          c001 = data[base + 1];
        float c010 = data[base + sy],     c011 = data[base + sy + 1];
        float c100 = data[base + sx],     c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy],c111 = data[base + sx + sy + 1];

        float d00 = c100 - c000, d01 = c101 - c001, d10 = c110 - c010, d11 = c111 - c011;
        float c00 = c000 + tx*d00, c01 = c001 + tx*d01, c10 = c010 + tx*d10, c11 = c011 + tx*d11;
        float c0 = c00 + ty*(c10 - c00), c1 = c01 + ty*(c11 - c01);
        float val = c0 + tz*(c1 - c0);

        float gx = ((1.0f - ty)*d00 + ty*d10)*(1.0f - tz) + ((1.0f - ty)*d01 + ty*d11)*tz;
        float gy = (c10 - c00)*(1.0f - tz) + (c11 - c01)*tz;
        float gz = c1 - c0;
        grad = Vec3(gx * inv_h, gy * inv_h, gz * inv_h);
        float gn = grad.norm();
        if (gn > 1e-6f) grad = grad * (1.0f / gn);
        return val;
    }
} sdf;

void envelope1D(const std::vector<float>& u, const std::vector<float>& w, const std::vector<int>& id,
                float q0, float h, int n_out, std::vector<int>& out_id) {
    int m = (int)u.size();
    if (m == 0) { std::fill(out_id.begin(), out_id.end(), -1); return; }
    std::vector<int> hull;
    std::vector<float> z(m + 1);
    hull.reserve(m);
    for (int i = 0; i < m; ++i) {
        if (!hull.empty() && std::abs(u[i] - u[hull.back()]) < 1e-6f) {
            if (w[i] < w[hull.back()]) {
                hull.back() = i;
                while (hull.size() >= 2) {
                    int a = hull[hull.size() - 2], b = hull.back();
                    float inter = ((w[b] + u[b]*u[b]) - (w[a] + u[a]*u[a])) / (2.0f * (u[b] - u[a]));
                    if (hull.size() >= 3 && inter <= z[hull.size() - 2]) hull.erase(hull.end() - 2);
                    else { z[hull.size() - 1] = inter; break; }
                }
                if (hull.size() == 1) z[0] = -1e30f;
            }
            continue;
        }
        while (!hull.empty()) {
            int a = hull.back();
            float inter = ((w[i] + u[i]*u[i]) - (w[a] + u[a]*u[a])) / (2.0f * (u[i] - u[a]));
            if (hull.size() >= 2 && inter <= z[hull.size() - 1]) hull.pop_back();
            else { z[hull.size()] = inter; break; }
        }
        if (hull.empty()) z[0] = -1e30f;
        hull.push_back(i);
    }
    z[hull.size()] = 1e30f;
    int k = 0, hs = (int)hull.size();
    for (int qi = 0; qi < n_out; ++qi) {
        float q = q0 + qi * h;
        while (k + 1 < hs && z[k + 1] < q) ++k;
        out_id[qi] = id[hull[k]];
    }
}

float distToCenterlineA(const Vec3& p) {
    float best2 = 1e30f;
    for (size_t i = 0; i + 1 < cl_a.size(); ++i) {
        Vec3 ab = cl_a[i+1] - cl_a[i];
        float len2 = ab.norm2();
        float t = (len2 > 1e-12f) ? (p - cl_a[i]).dot(ab) / len2 : 0.0f;
        t = std::max(0.0f, std::min(1.0f, t));
        float d2 = (p - (cl_a[i] + ab * t)).norm2();
        if (d2 < best2) best2 = d2;
    }
    return std::sqrt(best2);
}

void buildOrLoadSDF() {
    Vec3 bmin(1e30f, 1e30f, 1e30f), bmax(-1e30f, -1e30f, -1e30f);
    for (const auto& p : surf_a) {
        bmin.x = std::min(bmin.x, p.x); bmin.y = std::min(bmin.y, p.y); bmin.z = std::min(bmin.z, p.z);
        bmax.x = std::max(bmax.x, p.x); bmax.y = std::max(bmax.y, p.y); bmax.z = std::max(bmax.z, p.z);
    }
    sdf.bbox_min_surf = bmin;
    sdf.bbox_max_surf = bmax;
    float pad = 0.20f;
    sdf.h = 0.004f;
    sdf.inv_h = 1.0f / sdf.h;
    sdf.xmin = bmin.x - pad; sdf.ymin = bmin.y - pad; sdf.zmin = bmin.z - pad;
    sdf.nx = (int)std::ceil((bmax.x + pad - sdf.xmin) * sdf.inv_h) + 1;
    sdf.ny = (int)std::ceil((bmax.y + pad - sdf.ymin) * sdf.inv_h) + 1;
    sdf.nz = (int)std::ceil((bmax.z + pad - sdf.zmin) * sdf.inv_h) + 1;
    size_t total = (size_t)sdf.nx * sdf.ny * sdf.nz;

    std::ifstream cf("/app/sdf_cache.bin", std::ios::binary);
    if (cf) {
        sdf.data.resize(total);
        cf.read((char*)sdf.data.data(), total * sizeof(float));
        if (cf) {
            std::cout << "Loaded cached SDF (" << sdf.nx << "x" << sdf.ny << "x" << sdf.nz << ")." << std::endl;
            return;
        }
    }

    std::cout << "Building SDF..." << std::endl;
    std::vector<int> voronoi(total, -1);
    std::vector<std::vector<int>> row_seeds((size_t)sdf.ny * sdf.nz);
    for (int idx = 0; idx < (int)surf_a.size(); ++idx) {
        int j = std::clamp((int)std::round((surf_a[idx].y - sdf.ymin) * sdf.inv_h), 0, sdf.ny - 1);
        int k = std::clamp((int)std::round((surf_a[idx].z - sdf.zmin) * sdf.inv_h), 0, sdf.nz - 1);
        row_seeds[(size_t)j * sdf.nz + k].push_back(idx);
    }
    #pragma omp parallel
    {
        std::vector<float> u, w; std::vector<int> ids, out(sdf.nx);
        #pragma omp for schedule(dynamic, 64)
        for (int jk = 0; jk < sdf.ny * sdf.nz; ++jk) {
            auto& seeds = row_seeds[jk];
            if (seeds.empty()) continue;
            std::sort(seeds.begin(), seeds.end(), [&](int a, int b){ return surf_a[a].x < surf_a[b].x; });
            int j = jk / sdf.nz, k = jk % sdf.nz;
            float y = sdf.ymin + j * sdf.h, z = sdf.zmin + k * sdf.h;
            u.resize(seeds.size()); w.resize(seeds.size()); ids.resize(seeds.size());
            for (size_t s = 0; s < seeds.size(); ++s) {
                int id = seeds[s]; u[s] = surf_a[id].x;
                float dy = y - surf_a[id].y, dz = z - surf_a[id].z;
                w[s] = dy*dy + dz*dz; ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.xmin, sdf.h, sdf.nx, out);
            for (int i = 0; i < sdf.nx; ++i) voronoi[sdf.idx(i, j, k)] = out[i];
        }
    }
    row_seeds.clear(); row_seeds.shrink_to_fit();

    #pragma omp parallel
    {
        std::vector<int> cand, ids, out(sdf.ny); std::vector<float> u, w;
        #pragma omp for schedule(dynamic, 64)
        for (int ik = 0; ik < sdf.nx * sdf.nz; ++ik) {
            int i = ik / sdf.nz, k = ik % sdf.nz;
            float x = sdf.xmin + i * sdf.h, z = sdf.zmin + k * sdf.h;
            cand.clear();
            for (int j = 0; j < sdf.ny; ++j) { int id = voronoi[sdf.idx(i, j, k)]; if (id >= 0) cand.push_back(id); }
            if (cand.empty()) continue;
            std::sort(cand.begin(), cand.end(), [&](int a, int b){ return surf_a[a].y < surf_a[b].y; });
            u.resize(cand.size()); w.resize(cand.size()); ids.resize(cand.size());
            for (size_t s = 0; s < cand.size(); ++s) {
                int id = cand[s]; u[s] = surf_a[id].y;
                float dx = x - surf_a[id].x, dz = z - surf_a[id].z;
                w[s] = dx*dx + dz*dz; ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.ymin, sdf.h, sdf.ny, out);
            for (int j = 0; j < sdf.ny; ++j) voronoi[sdf.idx(i, j, k)] = out[j];
        }
    }

    sdf.data.resize(total);
    #pragma omp parallel
    {
        std::vector<int> cand, ids, out(sdf.nz); std::vector<float> u, w;
        #pragma omp for schedule(dynamic, 64)
        for (int ij = 0; ij < sdf.nx * sdf.ny; ++ij) {
            int i = ij / sdf.ny, j = ij % sdf.ny;
            float x = sdf.xmin + i * sdf.h, y = sdf.ymin + j * sdf.h;
            cand.clear();
            for (int k = 0; k < sdf.nz; ++k) { int id = voronoi[sdf.idx(i, j, k)]; if (id >= 0) cand.push_back(id); }
            u.resize(cand.size()); w.resize(cand.size()); ids.resize(cand.size());
            for (size_t s = 0; s < cand.size(); ++s) {
                int id = cand[s]; u[s] = surf_a[id].z;
                float dx = x - surf_a[id].x, dy = y - surf_a[id].y;
                w[s] = dx*dx + dy*dy; ids[s] = id;
            }
            envelope1D(u, w, ids, sdf.zmin, sdf.h, sdf.nz, out);
            for (int k = 0; k < sdf.nz; ++k) {
                int id = out[k];
                Vec3 g(x, y, sdf.zmin + k * sdf.h);
                Vec3 diff = g - surf_a[id];
                float d = diff.norm();
                float sign = 1.0f;
                if (d < 0.12f && diff.dot(norm_a_in[id]) > 0.0002f) {
                    if ((g - cl_a.front()).dot(out0_a) <= 0.002f &&
                        (g - cl_a.back()).dot(out1_a) <= 0.002f &&
                        distToCenterlineA(g) < 0.110f) {
                        sign = -1.0f;
                    }
                }
                sdf.data[sdf.idx(i, j, k)] = sign * d;
            }
        }
    }
    std::ofstream of("/app/sdf_cache.bin", std::ios::binary);
    of.write((const char*)sdf.data.data(), total * sizeof(float));
    std::cout << "Saved /app/sdf_cache.bin." << std::endl;
}

float checkClearance(const Pose& pose, float threshold, bool fine = true, bool check_ws = true) {
    if (check_ws) {
        if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
            pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) {
            return -1.0f;
        }
    }
    float R[9];
    pose.q.toMat(R);
    float min_d = 1e30f;
    float d_centers[66];

    for (int b = 0; b < 66; ++b) {
        float d = sdf.query(xform(R, pose.p, buckets[b].center));
        d_centers[b] = d;
        if (b >= 2 && b <= 63 && d < 0.097f + threshold) return d - 0.103f;
    }

    float active_band = std::max(threshold, 0.04f);
    bool any_active = false;
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + active_band) {
            any_active = true;
            for (const auto& pt : buckets[b].coarse_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        } else {
            float lb = d_centers[b] - buckets[b].r_max_fine;
            if (lb < min_d) min_d = lb;
        }
    }
    if (!fine || !any_active) return min_d;

    float fine_band = std::max(threshold + 0.008f, std::min(min_d, 0.03f));
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + fine_band) {
            for (const auto& pt : buckets[b].fine_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        }
    }
    return min_d;
}

bool retractPose(Pose& pose, float target_margin, int max_iters = 6) {
    for (int it = 0; it < max_iters; ++it) {
        if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
            pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) return false;
        float R[9];
        pose.q.toMat(R);
        Vec3 F(0,0,0), tau(0,0,0);
        float min_d = 1e30f;
        int n_act = 0;
        float sense = target_margin + 0.015f;

        for (int b = 0; b < 66; ++b) {
            float dc = sdf.query(xform(R, pose.p, buckets[b].center));
            if (dc > buckets[b].r_max_coarse + sense) {
                min_d = std::min(min_d, dc - buckets[b].r_max_coarse);
                continue;
            }
            for (const auto& pt : buckets[b].coarse_pts) {
                Vec3 rel(R[0]*pt.x + R[1]*pt.y + R[2]*pt.z,
                         R[3]*pt.x + R[4]*pt.y + R[5]*pt.z,
                         R[6]*pt.x + R[7]*pt.y + R[8]*pt.z);
                Vec3 g;
                float d = sdf.queryGrad(pose.p + rel, g);
                if (d < min_d) min_d = d;
                if (d < sense && g.norm2() > 0.5f) {
                    float w = (sense - d) * (sense - d); // quadratic weight focuses on tightest contact!
                    F = F + g * w;
                    tau = tau + rel.cross(g * w);
                    n_act++;
                }
            }
        }
        if (min_d >= target_margin && checkClearance(pose, target_margin, true) >= target_margin) return true;
        if (n_act == 0) break;
        float fn = F.norm(), tn = tau.norm();
        if (fn < 1e-9f && tn < 1e-9f) break;
        float step_need = std::clamp((target_margin - min_d) + 0.003f, 0.002f, 0.025f);
        float denom = std::sqrt(fn*fn + 0.4f*tn*tn) + 1e-9f;
        Vec3 dp = F * (step_need / denom);
        Vec3 dw = tau * (0.4f * step_need / denom);
        if (dp.norm() > 0.025f) dp = dp * (0.025f / dp.norm());
        if (dw.norm() > 0.05f)  dw = dw * (0.05f / dw.norm());
        pose.p = pose.p + dp;
        pose.q = (Quat::fromAxisAngle(dw) * pose.q).unit();
    }
    return checkClearance(pose, target_margin, true) >= target_margin;
}

bool edgeValid(const Pose& a, const Pose& b, float margin, bool fine = true, bool both_profiles = false) {
    float dp = (b.p - a.p).norm();
    float dq = quatAngleDist(a.q, b.q);
    int steps = std::max(2, (int)std::ceil(std::max(dp / 0.012f, dq / 0.016f)));
    for (int s = 1; s <= steps; ++s) {
        float t = (float)s / steps;
        Pose m{a.p + (b.p - a.p) * t, quatSlerp(a.q, b.q, t)};
        if (checkClearance(m, margin, fine) < margin) return false;
    }
    if (both_profiles && dp > 1e-5f && dq > 1e-5f) {
        float t_lin = dp / 0.1f, t_ang = dq / 0.1f, t_tot = std::max(t_lin, t_ang);
        for (int s = 1; s < steps; ++s) {
            float tau = ((float)s / steps) * t_tot;
            float sl = std::min(1.0f, tau / t_lin), sa = std::min(1.0f, tau / t_ang);
            if (std::abs(sl - sa) < 0.02f) continue;
            Pose m{a.p + (b.p - a.p) * sl, quatSlerp(a.q, b.q, sa)};
            if (checkClearance(m, margin, fine) < margin) return false;
        }
    }
    return true;
}

bool canEscapeAlongRay(const Pose& pose, float ray_margin, Vec3* best_dir = nullptr) {
    if (checkClearance(pose, ray_margin, true, true) < ray_margin) return false;
    static std::vector<Vec3> dirs;
    if (dirs.empty()) {
        const int N = 162;
        const float golden = 3.14159265359f * (3.0f - std::sqrt(5.0f));
        for (int i = 0; i < N; ++i) {
            float y = 1.0f - (2.0f * i) / (N - 1);
            float r = std::sqrt(std::max(0.0f, 1.0f - y*y));
            float th = golden * i;
            dirs.emplace_back(std::cos(th)*r, y, std::sin(th)*r);
        }
    }
    float best_min_c = -1.0f;
    Vec3 best_u(1,0,0);
    for (const auto& u : dirs) {
        bool ok = true;
        float min_c = 1e30f;
        for (float t = 0.03f; t <= 3.6f; t += 0.03f) {
            Pose sh{pose.p + u * t, pose.q};
            float c = checkClearance(sh, ray_margin, true, false);
            if (c < ray_margin) { ok = false; break; }
            min_c = std::min(min_c, c);
        }
        if (ok) {
            if (!best_dir) return true;
            if (min_c > best_min_c) { best_min_c = min_c; best_u = u; }
        }
    }
    if (best_min_c >= ray_margin) {
        if (best_dir) *best_dir = best_u;
        return true;
    }
    return false;
}

struct Node {
    Pose pose;
    int parent;
};

static inline float poseMetric(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.65f * quatAngleDist(a.q, b.q);
}

// KPIECE 6D Grid Cell Tracker for Frontier Exploration!
struct CellTree {
    std::vector<Node> nodes;
    struct Cell {
        std::vector<int> node_ids;
        int expansions = 0;
    };
    std::unordered_map<uint64_t, int> cell_map;
    std::vector<Cell> cells;

    static uint64_t hashPose(const Pose& pose) {
        Quat q = pose.q.canon();
        int ix = (int)std::floor((pose.p.x + 1.5f) / 0.14f);
        int iy = (int)std::floor((pose.p.y + 1.5f) / 0.14f);
        int iz = (int)std::floor((pose.p.z + 1.5f) / 0.14f);
        int qx = (int)std::floor((q.x + 1.1f) / 0.22f);
        int qy = (int)std::floor((q.y + 1.1f) / 0.22f);
        int qz = (int)std::floor((q.z + 1.1f) / 0.22f);
        uint64_t h = ((uint64_t)(ix & 0x3FF)) |
                     (((uint64_t)(iy & 0x3FF)) << 10) |
                     (((uint64_t)(iz & 0x3FF)) << 20) |
                     (((uint64_t)(qx & 0x1FF)) << 30) |
                     (((uint64_t)(qy & 0x1FF)) << 39) |
                     (((uint64_t)(qz & 0x1FF)) << 48);
        return h;
    }

    int addNode(const Pose& p, int parent) {
        int id = (int)nodes.size();
        nodes.push_back({p, parent});
        uint64_t h = hashPose(p);
        auto it = cell_map.find(h);
        if (it == cell_map.end()) {
            int cid = (int)cells.size();
            cell_map[h] = cid;
            cells.push_back({{id}, 0});
        } else {
            cells[it->second].node_ids.push_back(id);
        }
        return id;
    }

    int pickFrontierNode(std::mt19937& rng) {
        // Tournament selection of 5 random cells: pick cell with SMALLEST (expansions * 2 + node_ids.size())!
        int best_c = rng() % cells.size();
        int best_score = cells[best_c].expansions * 2 + (int)cells[best_c].node_ids.size();
        for (int k = 0; k < 5; ++k) {
            int c = rng() % cells.size();
            int sc = cells[c].expansions * 2 + (int)cells[c].node_ids.size();
            if (sc < best_score) { best_score = sc; best_c = c; }
        }
        cells[best_c].expansions++;
        const auto& v = cells[best_c].node_ids;
        return v[rng() % v.size()];
    }

    int nearest(const Pose& target, float* out_dist = nullptr) const {
        int best = 0;
        float best_d = 1e30f;
        int n = (int)nodes.size();
        for (int i = 0; i < n; ++i) {
            // Quick lower bound on p before acos
            float dp2 = (nodes[i].pose.p - target.p).norm2();
            if (dp2 >= best_d * best_d) continue;
            float d = std::sqrt(dp2) + 0.65f * quatAngleDist(nodes[i].pose.q, target.q);
            if (d < best_d) { best_d = d; best = i; }
        }
        if (out_dist) *out_dist = best_d;
        return best;
    }
};

// Local sliding exploration from a chosen frontier node along a random 6D direction!
int exploreSlide(CellTree& tree, int base_id, const Pose& dir_target, float margin, int max_steps) {
    int cur_id = base_id;
    for (int s = 0; s < max_steps; ++s) {
        const Pose& cur = tree.nodes[cur_id].pose;
        Vec3 dp = dir_target.p - cur.p;
        float lp = dp.norm();
        float lq = quatAngleDist(cur.q, dir_target.q);
        if (lp < 1e-4f && lq < 1e-4f) break;
        float frac = std::min({1.0f, 0.06f / std::max(lp, 1e-6f), 0.10f / std::max(lq, 1e-6f)});
        Pose cand{cur.p + dp * frac, quatSlerp(cur.q, dir_target.q, frac)};

        bool ok = (checkClearance(cand, margin, false) >= margin &&
                   checkClearance(cand, margin, true) >= margin);
        if (!ok) {
            Pose slid = cand;
            if (retractPose(slid, margin + 0.0015f, 5)) {
                if (poseMetric(slid, cur) > 0.015f && poseMetric(slid, dir_target) < poseMetric(cur, dir_target)) {
                    cand = slid;
                    ok = true;
                }
            }
        }
        if (!ok) break;
        if (!edgeValid(cur, cand, margin, true, false)) break;

        // Avoid cluttering tree with nearly identical poses unless reaching target
        float nd = 1e30f;
        tree.nearest(cand, &nd);
        if (nd < 0.032f && frac < 0.99f) break;

        cur_id = tree.addNode(cand, cur_id);
        if (frac >= 0.999f) break;
    }
    return cur_id;
}

int main(int argc, char** argv) {
    float plan_margin = (argc > 1) ? std::atof(argv[1]) : 0.0025f; // 2.5 mm initial discovery margin!
    std::ifstream f("/app/geometry.bin", std::ios::binary);
    auto readVec3s = [&](std::vector<Vec3>& v) {
        uint32_t n = 0; f.read((char*)&n, 4); v.resize(n); f.read((char*)v.data(), n * sizeof(Vec3));
    };
    f.read((char*)&pos_b0, sizeof(Vec3));
    f.read((char*)&max_r_l0, 4);
    f.read((char*)&out0_a, sizeof(Vec3));
    f.read((char*)&out1_a, sizeof(Vec3));
    readVec3s(surf_a); readVec3s(norm_a_in); readVec3s(cl_a);
    readVec3s(pts_b_l0); readVec3s(pts_b_l1); readVec3s(pts_b_l2);

    buckets.resize(66);
    for (int b = 0; b < 66; ++b) {
        buckets[b].center = pts_b_l0[b];
        buckets[b].r_max_coarse = 0.0f; buckets[b].r_max_fine = 0.0f;
    }
    auto assignBucket = [&](const Vec3& p) {
        int best = 0; float bd = 1e30f;
        for (int b = 0; b < 66; ++b) {
            float d2 = (p - buckets[b].center).norm2();
            if (d2 < bd) { bd = d2; best = b; }
        }
        return best;
    };
    for (size_t i = 0; i < pts_b_l1.size(); i += 3) {
        int b = assignBucket(pts_b_l1[i]);
        buckets[b].coarse_pts.push_back(pts_b_l1[i]);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, (pts_b_l1[i] - buckets[b].center).norm());
    }
    for (size_t i = 0; i < pts_b_l2.size(); i += 3) {
        int b = assignBucket(pts_b_l2[i]);
        buckets[b].fine_pts.push_back(pts_b_l2[i]);
        float r = (pts_b_l2[i] - buckets[b].center).norm();
        buckets[b].r_max_fine = std::max(buckets[b].r_max_fine, r);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, r);
    }

    buildOrLoadSDF();

    Pose start_pose{pos_b0, Quat(1,0,0,0)};
    std::cout << "Start clearance: " << checkClearance(start_pose, -1.0f, true) << " m\n";

    // Run 10 independent parallel KPIECE+Sliding explorers on 10 OpenMP threads, or shared search!
    // Wait: 10 independent parallel threads with different RNG seeds gives 10x probability per second AND zero lock contention!
    std::cout << "Launching 10-thread parallel KPIECE + Sliding-RRT search (margin=" << plan_margin << " m)..." << std::endl;

    volatile bool solved = false;
    std::vector<Pose> raw_solution;
    auto tp0 = std::chrono::high_resolution_clock::now();

    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        std::mt19937 rng(1000 + tid * 977);
        std::uniform_real_distribution<float> u01(0.0f, 1.0f);
        std::uniform_real_distribution<float> wx(-0.55f, 2.85f), wy(-0.55f, 2.35f), wz(-0.55f, 1.45f);
        auto randQuat = [&]() {
            float u1 = u01(rng), u2 = u01(rng)*6.2831853f, u3 = u01(rng)*6.2831853f;
            float s1 = std::sqrt(1.0f - u1), s2 = std::sqrt(u1);
            return Quat(s1*std::sin(u2), s1*std::cos(u2), s2*std::sin(u3), s2*std::cos(u3)).unit();
        };

        CellTree tA;
        tA.addNode(start_pose, -1);

        for (int iter = 1; iter <= 200000 && !solved; ++iter) {
            int base_id;
            Pose target;
            float r = u01(rng);
            if (r < 0.70f) {
                // KPIECE frontier expansion!
                base_id = tA.pickFrontierNode(rng);
                const Pose& bp = tA.nodes[base_id].pose;
                float scale = (u01(rng) < 0.5f) ? 0.25f : 0.70f;
                std::normal_distribution<float> gp(0.0f, scale), gq(0.0f, scale * 1.5f);
                target.p = bp.p + Vec3(gp(rng), gp(rng), gp(rng));
                target.q = (Quat::fromAxisAngle(Vec3(gq(rng), gq(rng), gq(rng))) * bp.q).unit();
            } else {
                // Global Voronoi pull + contact retraction
                target.p = Vec3(wx(rng), wy(rng), wz(rng));
                target.q = randQuat();
                if (u01(rng) < 0.5f) retractPose(target, plan_margin + 0.002f, 4);
                base_id = tA.nearest(target);
            }

            int end_id = exploreSlide(tA, base_id, target, plan_margin, 8);
            if (end_id != base_id) {
                const Pose& np = tA.nodes[end_id].pose;
                // Quick check if potentially escaped: distance from start > 0.85m
                if (poseMetric(np, start_pose) > 0.85f) {
                    if (canEscapeAlongRay(np, std::max(plan_margin, 0.010f))) {
                        #pragma omp critical
                        {
                            if (!solved) {
                                solved = true;
                                double el = std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - tp0).count();
                                std::cout << "[Thread " << tid << "] SOLVED in " << el << " s! iter=" << iter
                                          << ", nodes=" << tA.nodes.size() << ", cells=" << tA.cells.size() << std::endl;
                                for (int c = end_id; c != -1; c = tA.nodes[c].parent) {
                                    raw_solution.push_back(tA.nodes[c].pose);
                                }
                                std::reverse(raw_solution.begin(), raw_solution.end());
                            }
                        }
                    }
                }
            }

            if (tid == 0 && iter % 5000 == 0 && !solved) {
                double el = std::chrono::duration<double>(std::chrono::high_resolution_clock::now() - tp0).count();
                float max_m = 0.0f;
                for (const auto& n : tA.nodes) max_m = std::max(max_m, poseMetric(n.pose, start_pose));
                std::cout << "[T0] iter=" << iter << " (" << el << " s): nodes=" << tA.nodes.size()
                          << ", cells=" << tA.cells.size() << ", max_metric=" << max_m << std::endl;
            }
        }
    }

    if (!solved) {
        std::cout << "Did not solve within limit." << std::endl;
        return 2;
    }

    std::cout << "Raw path length: " << raw_solution.size() << " waypoints." << std::endl;

    // Truncate at earliest waypoint with clean 20mm escape ray + 1 step along ray!
    auto path = raw_solution;
    Vec3 esc_dir(0,0,1);
    for (size_t i = 1; i < path.size(); ++i) {
        Vec3 u;
        if (canEscapeAlongRay(path[i], 0.020f, &u)) {
            path.resize(i + 1);
            esc_dir = u;
            std::cout << "Truncated at waypoint " << i << " with 20mm escape ray ("
                      << u.x << ", " << u.y << ", " << u.z << ")" << std::endl;
            break;
        }
    }
    // Add 0.08m step along escape ray if valid so simulator's escape check passes with huge margin
    Pose extra = path.back();
    extra.p = extra.p + esc_dir * 0.08f;
    if (edgeValid(path.back(), extra, plan_margin, true, true) && canEscapeAlongRay(extra, 0.025f)) {
        path.push_back(extra);
    }

    // Subdivide to uniform fine resolution (~0.03m, 0.05rad)
    auto subdivide = [&](const std::vector<Pose>& in, float max_p, float max_q) {
        std::vector<Pose> out;
        out.push_back(in[0]);
        for (size_t i = 0; i + 1 < in.size(); ++i) {
            float dp = (in[i+1].p - in[i].p).norm();
            float dq = quatAngleDist(in[i].q, in[i+1].q);
            int k = std::max(1, (int)std::ceil(std::max(dp / max_p, dq / max_q)));
            for (int s = 1; s <= k; ++s) {
                float t = (float)s / k;
                out.push_back({in[i].p + (in[i+1].p - in[i].p)*t, quatSlerp(in[i].q, in[i+1].q, t)});
            }
        }
        return out;
    };

    path = subdivide(path, 0.03f, 0.05f);

    // Stage 1: Push EVERY interior waypoint to MAXIMIZE clearance (up to 25 mm!) while staying connected!
    for (int pass = 0; pass < 12; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            float cur_c = checkClearance(path[i], -1.0f, true);
            Pose cand = path[i];
            cand.p = (path[i-1].p + path[i].p * 2.0f + path[i+1].p) * 0.25f;
            cand.q = quatSlerp(quatSlerp(path[i-1].q, path[i+1].q, 0.5f), path[i].q, 0.5f);
            retractPose(cand, std::min(0.028f, cur_c + 0.008f), 3);
            float new_c = checkClearance(cand, -1.0f, true);
            float min_allowed = std::min(cur_c, 0.015f) - 0.0005f;
            if (new_c >= min_allowed &&
                edgeValid(path[i-1], cand, std::min(new_c, checkClearance(path[i-1], -1.0f, true)) - 0.001f, true, true) &&
                edgeValid(cand, path[i+1], std::min(new_c, checkClearance(path[i+1], -1.0f, true)) - 0.001f, true, true)) {
                path[i] = cand;
            }
        }
    }

    // Measure bottleneck clearance after Stage 1!
    float bottle = 1e30f;
    for (size_t i = 0; i + 1 < path.size(); ++i) {
        for (int s = 0; s <= 10; ++s) {
            float t = s / 10.0f;
            Pose m{path[i].p + (path[i+1].p - path[i].p)*t, quatSlerp(path[i].q, path[i+1].q, t)};
            bottle = std::min(bottle, checkClearance(m, -1.0f, true));
        }
    }
    std::cout << "Bottleneck clearance after clearance optimization: " << bottle << " m" << std::endl;

    float safe_m = std::max(plan_margin, std::min(0.012f, bottle - 0.0015f));
    std::cout << "Shortcutting with strict safety margin = " << safe_m << " m..." << std::endl;

    std::mt19937 srng(42);
    for (int sc = 0; sc < 2500 && path.size() > 3; ++sc) {
        int i = srng() % (path.size() - 2);
        int j = i + 2 + (srng() % (path.size() - i - 2));
        if (edgeValid(path[i], path[j], safe_m, true, true)) {
            auto seg = subdivide({path[i], path[j]}, 0.025f, 0.045f);
            std::vector<Pose> next;
            next.insert(next.end(), path.begin(), path.begin() + i);
            next.insert(next.end(), seg.begin(), seg.end());
            next.insert(next.end(), path.begin() + j + 1, path.end());
            path.swap(next);
        }
    }

    // One more clearance boost pass!
    for (int pass = 0; pass < 6; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            Pose cand = path[i];
            retractPose(cand, 0.025f, 2);
            if (checkClearance(cand, safe_m, true) >= safe_m &&
                edgeValid(path[i-1], cand, safe_m, true, true) &&
                edgeValid(cand, path[i+1], safe_m, true, true)) {
                path[i] = cand;
            }
        }
    }

    // Dynamic programming (shortest path DAG) over path waypoints to MINIMIZE EXACT MOVE ACTION COUNT!
    int N = (int)path.size();
    std::vector<int> dp_cost(N, 1e9), dp_prev(N, -1);
    dp_cost[0] = 0;
    for (int i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        for (int j = i + 1; j < N; ++j) {
            float d_lin = (path[j].p - path[i].p).norm();
            float d_ang = quatAngleDist(path[i].q, path[j].q);
            if (d_lin > 0.097f || d_ang > 0.194f) {
                if (j == i + 1) {
                    // Must allow single subdivided step if needed
                } else {
                    // Could still revisit if curved path loops back slightly, check upper bound
                    if (d_lin > 0.15f || d_ang > 0.30f) break;
                    continue;
                }
            }
            if (dp_cost[i] + 1 < dp_cost[j] && edgeValid(path[i], path[j], safe_m, true, true)) {
                dp_cost[j] = dp_cost[i] + 1;
                dp_prev[j] = i;
            }
        }
    }

    std::vector<Pose> actions;
    if (dp_cost[N - 1] < 1e8) {
        for (int c = N - 1; c != -1; c = dp_prev[c]) actions.push_back(path[c]);
        std::reverse(actions.begin(), actions.end());
    } else {
        actions = path;
    }

    // Verify final minimum clearance across both motion profiles!
    float min_sync = 1e30f, min_indep = 1e30f;
    for (size_t i = 0; i + 1 < actions.size(); ++i) {
        float dl = (actions[i+1].p - actions[i].p).norm();
        float da = quatAngleDist(actions[i].q, actions[i+1].q);
        for (int s = 0; s <= 30; ++s) {
            float t = s / 30.0f;
            Pose ms{actions[i].p + (actions[i+1].p - actions[i].p)*t, quatSlerp(actions[i].q, actions[i+1].q, t)};
            min_sync = std::min(min_sync, checkClearance(ms, -1.0f, true));
            if (dl > 1e-5f && da > 1e-5f) {
                float tl = dl / 0.1f, ta = da / 0.1f, tt = std::max(tl, ta);
                float tau = t * tt;
                Pose mi{actions[i].p + (actions[i+1].p - actions[i].p)*std::min(1.0f, tau/tl),
                        quatSlerp(actions[i].q, actions[i+1].q, std::min(1.0f, tau/ta))};
                min_indep = std::min(min_indep, checkClearance(mi, -1.0f, true));
            }
        }
    }

    std::cout << "=== OPTIMAL DISENTANGLEMENT PLAN ===" << std::endl;
    std::cout << "Move actions: " << (actions.size() - 1) << " (+1 grab = " << actions.size() << " / 198)" << std::endl;
    std::cout << "Min clearance (sync profile):  " << min_sync << " m" << std::endl;
    std::cout << "Min clearance (indep profile): " << min_indep << " m" << std::endl;
    Vec3 fdir;
    bool fok = canEscapeAlongRay(actions.back(), 0.020f, &fdir);
    std::cout << "Final escape valid (20mm): " << fok << " along (" << fdir.x << "," << fdir.y << "," << fdir.z << ")" << std::endl;

    std::ofstream out("/app/planned_path.txt");
    out.precision(8);
    for (const auto& a : actions) {
        out << a.p.x << " " << a.p.y << " " << a.p.z << " "
            << a.q.w << " " << a.q.x << " " << a.q.y << " " << a.q.z << "\n";
    }
    return 0;
}

