struct Vec3 {
    float x, y, z;
    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
    Vec3 operator+(const Vec3& o) const { return Vec3(x + o.x, y + o.y, z + o.z); }
    Vec3 operator-(const Vec3& o) const { return Vec3(x - o.x, y - o.y, z - o.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    float dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
    Vec3 cross(const Vec3& o) const {
        return Vec3(y * o.z - z * o.y, z * o.x - x * o.z, x * o.y - y * o.x);
    }
    float norm2() const { return x * x + y * y + z * z; }
    float norm() const { return std::sqrt(norm2()); }
};

struct Quat {
    float w, x, y, z;
    Quat() : w(1), x(0), y(0), z(0) {}
    Quat(float w_, float x_, float y_, float z_) : w(w_), x(x_), y(y_), z(z_) {}
    Quat unit() const {
        float n = std::sqrt(w*w + x*x + y*y + z*z);
        return (n > 1e-12f) ? Quat(w/n, x/n, y/n, z/n) : Quat(1,0,0,0);
    }
    Quat operator*(const Quat& o) const {
        return Quat(
            w*o.w - x*o.x - y*o.y - z*o.z,
            w*o.x + x*o.w + y*o.z - z*o.y,
            w*o.y - x*o.z + y*o.w + z*o.x,
            w*o.z + x*o.y - y*o.x + z*o.w
        );
    }
    void toMat(float R[9]) const {
        float xx = x*x, yy = y*y, zz = z*z;
        float xy = x*y, xz = x*z, yz = y*z;
        float wx = w*x, wy = w*y, wz = w*z;
        R[0] = 1.0f - 2.0f*(yy + zz); R[1] = 2.0f*(xy - wz);        R[2] = 2.0f*(xz + wy);
        R[3] = 2.0f*(xy + wz);        R[4] = 1.0f - 2.0f*(xx + zz); R[5] = 2.0f*(yz - wx);
        R[6] = 2.0f*(xz - wy);        R[7] = 2.0f*(yz + wx);        R[8] = 1.0f - 2.0f*(xx + yy);
    }
    static Quat fromAxisAngle(const Vec3& aa) {
        float ang = aa.norm();
        if (ang < 1e-8f) return Quat(1.0f, 0.5f*aa.x, 0.5f*aa.y, 0.5f*aa.z).unit();
        float s = std::sin(0.5f * ang) / ang;
        return Quat(std::cos(0.5f * ang), aa.x * s, aa.y * s, aa.z * s);
    }
};

static inline float quatAngleDist(const Quat& a, const Quat& b) {
    float d = std::abs(a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z);
    if (d > 1.0f) d = 1.0f;
    return 2.0f * std::acos(d);
}

static inline Quat quatSlerp(const Quat& a, Quat b, float t) {
    float d = a.w*b.w + a.x*b.x + a.y*b.y + a.z*b.z;
    if (d < 0.0f) { d = -d; b = Quat(-b.w, -b.x, -b.y, -b.z); }
    if (d > 0.9995f) {
        return Quat(a.w + t*(b.w - a.w), a.x + t*(b.x - a.x),
                    a.y + t*(b.y - a.y), a.z + t*(b.z - a.z)).unit();
    }
    float theta = std::acos(std::min(1.0f, d));
    float st = std::sin(theta);
    float wa = std::sin((1.0f - t)*theta) / st;
    float wb = std::sin(t*theta) / st;
    return Quat(wa*a.w + wb*b.w, wa*a.x + wb*b.x, wa*a.y + wb*b.y, wa*a.z + wb*b.z).unit();
}

struct Pose {
    Vec3 p;
    Quat q;
};

static inline Vec3 xform(const float R[9], const Vec3& t, const Vec3& v) {
    return Vec3(
        R[0]*v.x + R[1]*v.y + R[2]*v.z + t.x,
        R[3]*v.x + R[4]*v.y + R[5]*v.z + t.y,
        R[6]*v.x + R[7]*v.y + R[8]*v.z + t.z
    );
}

Vec3 pos_b0, out0_a, out1_a;
float max_r_l0;
std::vector<Vec3> surf_a, norm_a_in, cl_a;
std::vector<Vec3> pts_b_l0, pts_b_l1, pts_b_l2;

std::vector<Vec3> loop_a_dec;
std::vector<Vec3> loop_b_body_dec;

float computeLinkingNumber(const Pose& pose) {
    float R[9];
    pose.q.toMat(R);
    int M = (int)loop_b_body_dec.size();
    std::vector<Vec3> Lb(M);
    for (int i = 0; i < M; ++i) Lb[i] = xform(R, pose.p, loop_b_body_dec[i]);
    int Na = (int)loop_a_dec.size();
    float lk = 0.0f;
    for (int i = 0; i < Na; ++i) {
        int i2 = (i + 1) % Na;
        Vec3 r1 = (loop_a_dec[i] + loop_a_dec[i2]) * 0.5f;
        Vec3 dr1 = loop_a_dec[i2] - loop_a_dec[i];
        for (int j = 0; j < M; ++j) {
            int j2 = (j + 1) % M;
            Vec3 r2 = (Lb[j] + Lb[j2]) * 0.5f;
            Vec3 dr2 = Lb[j2] - Lb[j];
            Vec3 diff = r1 - r2;
            float d2 = diff.norm2();
            if (d2 < 1e-5f) return 999.0f; // segments touching!
            float d3 = d2 * std::sqrt(d2);
            lk += diff.dot(dr1.cross(dr2)) / d3;
        }
    }
    return lk / (4.0f * 3.14159265359f);
}

struct Bucket {
    Vec3 center;
    float r_max_coarse;
    float r_max_fine;
    std::vector<Vec3> coarse_pts;
    std::vector<Vec3> fine_pts;
};
std::vector<Bucket> buckets;

struct SDFGrid {
    float xmin, ymin, zmin, h, inv_h;
    int nx, ny, nz;
    Vec3 bbox_min_surf, bbox_max_surf;
    std::vector<float> data;

    inline float query(const Vec3& p) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 0.0f || fy < 0.0f || fz < 0.0f || fx >= nx - 1.001f || fy >= ny - 1.001f || fz >= nz - 1.001f) {
            float dx = std::max({0.0f, bbox_min_surf.x - p.x, p.x - bbox_max_surf.x});
            float dy = std::max({0.0f, bbox_min_surf.y - p.y, p.y - bbox_max_surf.y});
            float dz = std::max({0.0f, bbox_min_surf.z - p.z, p.z - bbox_max_surf.z});
            return std::sqrt(dx*dx + dy*dy + dz*dz);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base],          c001 = data[base + 1];
        float c010 = data[base + sy],     c011 = data[base + sy + 1];
        float c100 = data[base + sx],     c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy],c111 = data[base + sx + sy + 1];
        float c00 = c000 + tx*(c100 - c000), c01 = c001 + tx*(c101 - c001);
        float c10 = c010 + tx*(c110 - c010), c11 = c011 + tx*(c111 - c011);
        float c0 = c00 + ty*(c10 - c00),     c1 = c01 + ty*(c11 - c01);
        return c0 + tz*(c1 - c0);
    }

    inline float queryGrad(const Vec3& p, Vec3& grad) const {
        float fx = (p.x - xmin) * inv_h;
        float fy = (p.y - ymin) * inv_h;
        float fz = (p.z - zmin) * inv_h;
        if (fx < 1.0f || fy < 1.0f || fz < 1.0f || fx >= nx - 2.001f || fy >= ny - 2.001f || fz >= nz - 2.001f) {
            grad = Vec3(0, 0, 0);
            return query(p);
        }
        int i = (int)fx, j = (int)fy, k = (int)fz;
        float tx = fx - i, ty = fy - j, tz = fz - k;
        size_t base = ((size_t)i * ny + j) * nz + k;
        size_t sy = nz, sx = (size_t)ny * nz;
        float c000 = data[base],          c001 = data[base + 1];
        float c010 = data[base + sy],     c011 = data[base + sy + 1];
        float c100 = data[base + sx],     c101 = data[base + sx + 1];
        float c110 = data[base + sx + sy],c111 = data[base + sx + sy + 1];

        float d00 = c100 - c000, d01 = c101 - c001, d10 = c110 - c010, d11 = c111 - c011;
        float c00 = c000 + tx*d00, c01 = c001 + tx*d01, c10 = c010 + tx*d10, c11 = c011 + tx*d11;
        float c0 = c00 + ty*(c10 - c00), c1 = c01 + ty*(c11 - c01);
        float val = c0 + tz*(c1 - c0);

        float gx = ((1.0f - ty)*d00 + ty*d10)*(1.0f - tz) + ((1.0f - ty)*d01 + ty*d11)*tz;
        float gy = (c10 - c00)*(1.0f - tz) + (c11 - c01)*tz;
        float gz = c1 - c0;
        grad = Vec3(gx * inv_h, gy * inv_h, gz * inv_h);
        float gn = grad.norm();
        if (gn > 1e-6f) grad = grad * (1.0f / gn);
        return val;
    }
} sdf;

float checkClearance(const Pose& pose, float threshold, bool fine = false, bool check_ws = true) {
    if (check_ws) {
        if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
            pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) {
            return -1.0f;
        }
    }
    float R[9];
    pose.q.toMat(R);
    float min_d = 1e30f;
    float d_centers[66];

    for (int b = 0; b < 66; ++b) {
        float d = sdf.query(xform(R, pose.p, buckets[b].center));
        d_centers[b] = d;
        if (b >= 2 && b <= 63 && d < 0.097f + threshold) return d - 0.103f;
    }

    float active_band = std::max(threshold, 0.035f);
    bool any_active = false;
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + active_band) {
            any_active = true;
            for (const auto& pt : buckets[b].coarse_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        } else {
            float lb = d_centers[b] - buckets[b].r_max_fine;
            if (lb < min_d) min_d = lb;
        }
    }
    if (!fine || !any_active) return min_d;

    float fine_band = std::max(threshold + 0.008f, std::min(min_d, 0.030f));
    for (int b = 0; b < 66; ++b) {
        if (d_centers[b] <= buckets[b].r_max_fine + fine_band) {
            for (const auto& pt : buckets[b].fine_pts) {
                float d = sdf.query(xform(R, pose.p, pt));
                if (d < threshold) return d;
                if (d < min_d) min_d = d;
            }
        }
    }
    return min_d;
}

// High-precision fine-point softmin clearance ascent (maximizes bottleneck clearance!)
bool retractPose(Pose& pose, float target_margin, int max_iters = 6, bool use_fine = false) {
    for (int it = 0; it < max_iters; ++it) {
        if (pose.p.x < -0.72f || pose.p.y < -0.72f || pose.p.z < -0.72f ||
            pose.p.x >  3.12f || pose.p.y >  3.12f || pose.p.z >  3.12f) return false;
        float R[9];
        pose.q.toMat(R);
        Vec3 F(0,0,0), tau(0,0,0);
        float min_d = 1e30f;
        float w_sum = 0.0f;
        float sense = target_margin + 0.014f;

        for (int b = 0; b < 66; ++b) {
            float dc = sdf.query(xform(R, pose.p, buckets[b].center));
            if (dc > buckets[b].r_max_fine + sense) {
                min_d = std::min(min_d, dc - buckets[b].r_max_fine);
                continue;
            }
            const auto& pts = use_fine ? buckets[b].fine_pts : buckets[b].coarse_pts;
            for (const auto& pt : pts) {
                Vec3 rel(R[0]*pt.x + R[1]*pt.y + R[2]*pt.z,
                         R[3]*pt.x + R[4]*pt.y + R[5]*pt.z,
                         R[6]*pt.x + R[7]*pt.y + R[8]*pt.z);
                Vec3 g;
                float d = sdf.queryGrad(pose.p + rel, g);
                if (d < min_d) min_d = d;
                if (d < sense && g.norm2() > 0.5f) {
                    // Exponential softmin weight strongly prioritizes the single closest point(s)!
                    float w = std::exp((sense - d) * 180.0f);
                    F = F + g * w;
                    tau = tau + rel.cross(g * w);
                    w_sum += w;
                }
            }
        }
        if (min_d >= target_margin && checkClearance(pose, target_margin, true) >= target_margin) return true;
        if (w_sum < 1e-9f) break;
        F = F * (1.0f / w_sum);
        tau = tau * (1.0f / w_sum);
        float fn = F.norm(), tn = tau.norm();
        if (fn < 1e-9f && tn < 1e-9f) break;
        float step_need = std::clamp((target_margin - min_d) * 0.65f + 0.0015f, 0.001f, 0.018f);
        float denom = std::sqrt(fn*fn + 0.45f*tn*tn) + 1e-9f;
        Vec3 dp = F * (step_need / denom);
        Vec3 dw = tau * (0.45f * step_need / denom);
        Pose next_p{pose.p + dp, (Quat::fromAxisAngle(dw) * pose.q).unit()};
        if (use_fine) {
            // Line search: only accept if true fine clearance actually improves or exceeds target_margin!
            float c_old = min_d;
            bool accepted = false;
            float alpha = 1.0f;
            for (int ls = 0; ls < 4; ++ls) {
                Pose trial{pose.p + dp * alpha, (Quat::fromAxisAngle(dw * alpha) * pose.q).unit()};
                float c_new = checkClearance(trial, c_old - 0.0005f, true);
                if (c_new > c_old || c_new >= target_margin) {
                    pose = trial;
                    accepted = true;
                    break;
                }
                alpha *= 0.45f;
            }
            if (!accepted) break;
        } else {
            pose = next_p;
        }
    }
    return checkClearance(pose, target_margin, true) >= target_margin;
}

bool edgeValid(const Pose& a, const Pose& b, float margin, bool fine = true, bool both_profiles = false) {
    float dp = (b.p - a.p).norm();
    float dq = quatAngleDist(a.q, b.q);
    int steps = std::max(4, (int)std::ceil(std::max(dp / 0.006f, dq / 0.009f)));
    for (int s = 1; s <= steps; ++s) {
        float t = (float)s / steps;
        Pose m{a.p + (b.p - a.p) * t, quatSlerp(a.q, b.q, t)};
        if (checkClearance(m, margin, fine) < margin) return false;
    }
    if (both_profiles && dp > 1e-5f && dq > 1e-5f) {
        float t_lin = dp / 0.1f, t_ang = dq / 0.1f, t_tot = std::max(t_lin, t_ang);
        for (int s = 1; s < steps; ++s) {
            float tau = ((float)s / steps) * t_tot;
            float sl = std::min(1.0f, tau / t_lin), sa = std::min(1.0f, tau / t_ang);
            if (std::abs(sl - sa) < 0.01f) continue;
            Pose m{a.p + (b.p - a.p) * sl, quatSlerp(a.q, b.q, sa)};
            if (checkClearance(m, margin, fine) < margin) return false;
        }
    }
    return true;
}

float edgeMinClearance(const Pose& a, const Pose& b, bool both_profiles = true) {
    float dp = (b.p - a.p).norm();
    float dq = quatAngleDist(a.q, b.q);
    int steps = std::max(8, (int)std::ceil(std::max(dp / 0.005f, dq / 0.008f)));
    float mc = 1e30f;
    for (int s = 0; s <= steps; ++s) {
        float t = (float)s / steps;
        Pose m{a.p + (b.p - a.p) * t, quatSlerp(a.q, b.q, t)};
        mc = std::min(mc, checkClearance(m, -1.0f, true));
        if (both_profiles && dp > 1e-5f && dq > 1e-5f) {
            float tl = dp / 0.1f, ta = dq / 0.1f, tt = std::max(tl, ta);
            float tau = t * tt;
            Pose mi{a.p + (b.p - a.p) * std::min(1.0f, tau/tl),
                    quatSlerp(a.q, b.q, std::min(1.0f, tau/ta))};
            mc = std::min(mc, checkClearance(mi, -1.0f, true));
        }
    }
    return mc;
}

bool canEscapeAlongRay(const Pose& pose, float ray_margin, Vec3* best_dir = nullptr) {
    if (checkClearance(pose, ray_margin, true, true) < ray_margin) return false;
    static std::vector<Vec3> dirs;
    if (dirs.empty()) {
        const int N = 200;
        const float golden = 3.14159265359f * (3.0f - std::sqrt(5.0f));
        for (int i = 0; i < N; ++i) {
            float y = 1.0f - (2.0f * i) / (N - 1);
            float r = std::sqrt(std::max(0.0f, 1.0f - y*y));
            float th = golden * i;
            dirs.emplace_back(std::cos(th)*r, y, std::sin(th)*r);
        }
    }
    float best_min_c = -1.0f;
    Vec3 best_u(1,0,0);
    for (const auto& u : dirs) {
        bool ok = true;
        float min_c = 1e30f;
        for (float t = 0.025f; t <= 3.6f; t += 0.025f) {
            Pose sh{pose.p + u * t, pose.q};
            float c = checkClearance(sh, ray_margin, true, false);
            if (c < ray_margin) { ok = false; break; }
            min_c = std::min(min_c, c);
        }
        if (ok) {
            if (!best_dir) return true;
            if (min_c > best_min_c) { best_min_c = min_c; best_u = u; }
        }
    }
    if (best_min_c >= ray_margin) {
        if (best_dir) *best_dir = best_u;
        return true;
    }
    return false;
}

float segSegDist(const Vec3& a0, const Vec3& a1, const Vec3& b0, const Vec3& b1) {
    Vec3 u = a1 - a0, v = b1 - b0, w = a0 - b0;
    float a = u.dot(u), b = u.dot(v), c = v.dot(v), d = u.dot(w), e = v.dot(w);
    float D = a*c - b*b;
    float sN, sD = D, tN, tD = D;
    if (D < 1e-7f) { sN = 0.0f; sD = 1.0f; tN = e; tD = c; }
    else {
        sN = (b*e - c*d); tN = (a*e - b*d);
        if (sN < 0.0f) { sN = 0.0f; tN = e; tD = c; }
        else if (sN > sD) { sN = sD; tN = e + b; tD = c; }
    }
    if (tN < 0.0f) {
        tN = 0.0f;
        if (-d < 0.0f) sN = 0.0f; else if (-d > a) sN = sD; else { sN = -d; sD = a; }
    } else if (tN > tD) {
        tN = tD;
        if ((-d + b) < 0.0f) sN = 0.0f; else if ((-d + b) > a) sN = sD; else { sN = (-d + b); sD = a; }
    }
    float sc = (std::abs(sN) < 1e-7f ? 0.0f : sN / sD);
    float tc = (std::abs(tN) < 1e-7f ? 0.0f : tN / tD);
    return (w + (u * sc) - (v * tc)).norm();
}

struct Node { Pose pose; int parent; };
static inline float poseMetric(const Pose& a, const Pose& b) {
    return (a.p - b.p).norm() + 0.65f * quatAngleDist(a.q, b.q);
}

int nearestNode(const std::vector<Node>& tree, const Pose& target, float* out_d = nullptr) {
    int best = 0; float best_d = 1e30f;
    for (int i = 0; i < (int)tree.size(); ++i) {
        float dp2 = (tree[i].pose.p - target.p).norm2();
        if (dp2 >= best_d * best_d) continue;
        float d = std::sqrt(dp2) + 0.65f * quatAngleDist(tree[i].pose.q, target.q);
        if (d < best_d) { best_d = d; best = i; }
    }
    if (out_d) *out_d = best_d;
    return best;
}

bool biRRTConnect(const Pose& start, const std::vector<Pose>& goals, float margin,
                  int max_iters, int seed, std::vector<Pose>& out_path) {
    std::vector<Node> tA, tB;
    tA.push_back({start, -1});
    for (const auto& g : goals) tB.push_back({g, -1});
    std::mt19937 rng(seed);
    std::uniform_real_distribution<float> u01(0.0f, 1.0f);
    Vec3 c_mid = (start.p + goals[0].p) * 0.5f;

    auto stepToward = [&](std::vector<Node>& tree, const Pose& target, int& out_id) -> int {
        int nid = nearestNode(tree, target);
        const Pose& cur = tree[nid].pose;
        Vec3 dp = target.p - cur.p;
        float lp = dp.norm(), lq = quatAngleDist(cur.q, target.q);
        float frac = std::min({1.0f, 0.06f / std::max(lp, 1e-6f), 0.10f / std::max(lq, 1e-6f)});
        Pose cand{cur.p + dp * frac, quatSlerp(cur.q, target.q, frac)};

        bool ok = (checkClearance(cand, margin, false) >= margin &&
                   checkClearance(cand, margin, true) >= margin);
        if (!ok) {
            Pose slid = cand;
            if (retractPose(slid, margin + 0.002f, 4, false)) {
                if (poseMetric(slid, cur) > 0.012f && poseMetric(slid, target) < poseMetric(cur, target) - 0.004f) {
                    cand = slid;
                    ok = true;
                }
            }
        }
        if (!ok) return 0;
        if (!edgeValid(cur, cand, margin, true, false)) return 0;
        float nd = 1e30f;
        nearestNode(tree, cand, &nd);
        if (nd < 0.020f && frac < 0.99f) return 0;
        out_id = (int)tree.size();
        tree.push_back({cand, nid});
        return (poseMetric(cand, target) < 0.015f) ? 2 : 1;
    };

    bool swapped = false;
    for (int it = 0; it < max_iters; ++it) {
        Pose q_rand;
        float r = u01(rng);
        if (r < 0.22f) {
            const auto& other = !swapped ? tB : tA;
            q_rand = other[rng() % other.size()].pose;
        } else if (r < 0.68f) {
            const auto& own = !swapped ? tA : tB;
            const Pose& b = own[rng() % own.size()].pose;
            std::normal_distribution<float> gp(0.0f, 0.24f), gq(0.0f, 0.42f);
            q_rand.p = b.p + Vec3(gp(rng), gp(rng), gp(rng));
            q_rand.q = (Quat::fromAxisAngle(Vec3(gq(rng), gq(rng), gq(rng))) * b.q).unit();
            if (u01(rng) < 0.45f) retractPose(q_rand, margin + 0.002f, 3, false);
        } else {
            std::normal_distribution<float> gp(0.0f, 0.7f);
            float u1 = u01(rng), u2 = u01(rng)*6.2831853f, u3 = u01(rng)*6.2831853f;
            q_rand.p = c_mid + Vec3(gp(rng), gp(rng), gp(rng) * 0.6f);
            q_rand.q = Quat(std::sqrt(1-u1)*std::sin(u2), std::sqrt(1-u1)*std::cos(u2),
                            std::sqrt(u1)*std::sin(u3), std::sqrt(u1)*std::cos(u3)).unit();
        }

        auto& tree1 = !swapped ? tA : tB;
        auto& tree2 = !swapped ? tB : tA;
        int id1 = -1;
        if (stepToward(tree1, q_rand, id1) > 0) {
            const Pose& tgt = tree1[id1].pose;
            int id2 = -1;
            for (int cs = 0; cs < 25; ++cs) {
                int st = stepToward(tree2, tgt, id2);
                if (st == 0) break;
                if (st == 2 || edgeValid(tree2[id2].pose, tgt, margin, true, false)) {
                    int a_id = !swapped ? id1 : id2;
                    int b_id = !swapped ? id2 : id1;
                    out_path.clear();
                    for (int c = a_id; c != -1; c = tA[c].parent) out_path.push_back(tA[c].pose);
                    std::reverse(out_path.begin(), out_path.end());
                    for (int c = b_id; c != -1; c = tB[c].parent) out_path.push_back(tB[c].pose);
                    return true;
                }
            }
        }
        swapped = !swapped;
    }
    return false;
}

int main() {
    std::ifstream f("/app/geometry.bin", std::ios::binary);
    auto readVec3s = [&](std::vector<Vec3>& v) {
        uint32_t n = 0; f.read((char*)&n, 4); v.resize(n); f.read((char*)v.data(), n * sizeof(Vec3));
    };
    f.read((char*)&pos_b0, sizeof(Vec3));
    f.read((char*)&max_r_l0, 4);
    f.read((char*)&out0_a, sizeof(Vec3));
    f.read((char*)&out1_a, sizeof(Vec3));
    readVec3s(surf_a); readVec3s(norm_a_in); readVec3s(cl_a);
    readVec3s(pts_b_l0); readVec3s(pts_b_l1); readVec3s(pts_b_l2);

    Vec3 bmin(1e30f, 1e30f, 1e30f), bmax(-1e30f, -1e30f, -1e30f);
    for (const auto& p : surf_a) {
        bmin.x = std::min(bmin.x, p.x); bmin.y = std::min(bmin.y, p.y); bmin.z = std::min(bmin.z, p.z);
        bmax.x = std::max(bmax.x, p.x); bmax.y = std::max(bmax.y, p.y); bmax.z = std::max(bmax.z, p.z);
    }
    sdf.bbox_min_surf = bmin; sdf.bbox_max_surf = bmax;
    float pad = 0.20f; sdf.h = 0.004f; sdf.inv_h = 1.0f / sdf.h;
    sdf.xmin = bmin.x - pad; sdf.ymin = bmin.y - pad; sdf.zmin = bmin.z - pad;
    sdf.nx = (int)std::ceil((bmax.x + pad - sdf.xmin) * sdf.inv_h) + 1;
    sdf.ny = (int)std::ceil((bmax.y + pad - sdf.ymin) * sdf.inv_h) + 1;
    sdf.nz = (int)std::ceil((bmax.z + pad - sdf.zmin) * sdf.inv_h) + 1;
    size_t total = (size_t)sdf.nx * sdf.ny * sdf.nz;
    sdf.data.resize(total);
    std::ifstream cf("/app/sdf_cache.bin", std::ios::binary);
    cf.read((char*)sdf.data.data(), total * sizeof(float));

    buckets.resize(66);
    for (int b = 0; b < 66; ++b) {
        buckets[b].center = pts_b_l0[b];
        buckets[b].r_max_coarse = 0.0f; buckets[b].r_max_fine = 0.0f;
    }
    auto assignBucket = [&](const Vec3& p) {
        int best = 0; float bd = 1e30f;
        for (int b = 0; b < 66; ++b) {
            float d2 = (p - buckets[b].center).norm2();
            if (d2 < bd) { bd = d2; best = b; }
        }
        return best;
    };
    for (size_t i = 0; i < pts_b_l1.size(); i += 2) {
        int b = assignBucket(pts_b_l1[i]);
        buckets[b].coarse_pts.push_back(pts_b_l1[i]);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, (pts_b_l1[i] - buckets[b].center).norm());
    }
    // Use ALL 66,079 points of pts_b_l2 for full sub-millimeter precision!
    for (size_t i = 0; i < pts_b_l2.size(); ++i) {
        int b = assignBucket(pts_b_l2[i]);
        buckets[b].fine_pts.push_back(pts_b_l2[i]);
        float r = (pts_b_l2[i] - buckets[b].center).norm();
        buckets[b].r_max_fine = std::max(buckets[b].r_max_fine, r);
        buckets[b].r_max_coarse = std::max(buckets[b].r_max_coarse, r);
    }

    float az = 20.0f * 3.14159265359f / 180.0f, ax = 15.0f * 3.14159265359f / 180.0f;
    float Rz[9] = {std::cos(az), std::sin(az), 0, -std::sin(az), std::cos(az), 0, 0, 0, 1};
    float Rx[9] = {1, 0, 0, 0, std::cos(ax), std::sin(ax), 0, -std::sin(ax), std::cos(ax)};
    float Rab[9];
    for (int i=0;i<3;++i) for (int j=0;j<3;++j)
        Rab[3*i+j] = Rz[3*i+0]*Rx[0*3+j] + Rz[3*i+1]*Rx[1*3+j] + Rz[3*i+2]*Rx[2*3+j];
    Vec3 tab(0.1565473f, 0.017367f, 0.3474787f);
    std::vector<Vec3> cl_b_body(cl_a.size());
    for (size_t i = 0; i < cl_a.size(); ++i) cl_b_body[i] = xform(Rab, tab - pos_b0, cl_a[i]);

    // Build closed loops [69..228] PLUS 12-subdivided closing segments [228 -> 69] so Lk is exact!
    for (int i = 69; i <= 228; i += 5) {
        loop_a_dec.push_back(cl_a[i]);
        loop_b_body_dec.push_back(cl_b_body[i]);
    }
    for (int k = 0; k < 12; ++k) {
        float f = (float)k / 12.0f;
        loop_a_dec.push_back(cl_a[228] * (1.0f - f) + cl_a[69] * f);
        loop_b_body_dec.push_back(cl_b_body[228] * (1.0f - f) + cl_b_body[69] * f);
    }

    Vec3 sa0 = cl_a[69], sa1 = cl_a[228];
    Vec3 ma = (sa0 + sa1) * 0.5f;
    Vec3 sb0_body = cl_b_body[69], sb1_body = cl_b_body[228];
    Vec3 mb_body = (sb0_body + sb1_body) * 0.5f;

    Pose start_pose{pos_b0, Quat(1,0,0,0)};
    std::cout << "Start pose clearance=" << checkClearance(start_pose, -1.0f, true)
              << ", exact Lk=" << computeLinkingNumber(start_pose) << std::endl;

    struct Keyhole { Pose pose; float clearance; float seg_dist; };
    std::vector<Keyhole> keyholes;

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        std::mt19937 rng(2026 + tid * 1337);
        std::uniform_real_distribution<float> u01(0.0f, 1.0f), ud(-0.08f, 0.08f);
        std::vector<Keyhole> local_kh;

        #pragma omp for
        for (int s = 0; s < 6000000; ++s) {
            float u1 = u01(rng), u2 = u01(rng)*6.2831853f, u3 = u01(rng)*6.2831853f;
            Quat q(std::sqrt(1-u1)*std::sin(u2), std::sqrt(1-u1)*std::cos(u2),
                   std::sqrt(u1)*std::sin(u3), std::sqrt(u1)*std::cos(u3));
            float R[9]; q.toMat(R);
            Vec3 p = (ma + Vec3(ud(rng), ud(rng), ud(rng))) - xform(R, Vec3(0,0,0), mb_body);
            if (segSegDist(sa0, sa1, xform(R, p, sb0_body), xform(R, p, sb1_body)) > 0.025f) continue;

            Pose cand{p, q};
            if (checkClearance(cand, -0.010f, false) > -0.010f) {
                retractPose(cand, 0.018f, 5, true);
                float cf = checkClearance(cand, 0.004f, true);
                if (cf >= 0.004f) {
                    float R2[9]; cand.q.toMat(R2);
                    float sd2 = segSegDist(sa0, sa1, xform(R2, cand.p, sb0_body), xform(R2, cand.p, sb1_body));
                    if (sd2 < 0.045f) local_kh.push_back({cand, cf, sd2});
                }
            }
        }
        #pragma omp critical
        keyholes.insert(keyholes.end(), local_kh.begin(), local_kh.end());
    }

    std::sort(keyholes.begin(), keyholes.end(), [](const Keyhole& a, const Keyhole& b){
        return a.clearance > b.clearance;
    });
    std::cout << "Found " << keyholes.size() << " high-clearance keyholes (>=4mm)!\n";
    for (size_t i = 0; i < std::min((size_t)8, keyholes.size()); ++i) {
        std::cout << "  KH[" << i << "]: clear=" << keyholes[i].clearance
                  << " m, seg_dist=" << keyholes[i].seg_dist << " m\n";
    }

    struct Bridge {
        Pose in_pose, mid_pose, out_pose;
        float min_clear;
    };
    std::vector<Bridge> bridges;
    int n_test = std::min((int)keyholes.size(), 300);

    #pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < n_test; ++i) {
        std::mt19937 rng(500 + i);
        std::normal_distribution<float> gp(0.0f, 0.07f), gq(0.0f, 0.12f);
        Pose mid = keyholes[i].pose;
        Pose best_in = mid, best_out = mid;
        float best_in_c = -1.0f, best_out_c = -1.0f;
        for (int t = 0; t < 350; ++t) {
            Pose p{mid.p + Vec3(gp(rng), gp(rng), gp(rng)),
                   (Quat::fromAxisAngle(Vec3(gq(rng), gq(rng), gq(rng))) * mid.q).unit()};
            retractPose(p, 0.018f, 3, true);
            float c = checkClearance(p, 0.0045f, true);
            if (c < 0.0045f) continue;
            float R[9]; p.q.toMat(R);
            float sd = segSegDist(sa0, sa1, xform(R, p.p, sb0_body), xform(R, p.p, sb1_body));
            if (sd < 0.025f) continue; // make sure clearly past the crossing sheet so Lk is well-defined!
            float lk = computeLinkingNumber(p);
            if (std::abs(lk - 1.0f) < 0.12f) {
                float ec = edgeMinClearance(p, mid, true);
                if (ec > best_in_c) { best_in_c = ec; best_in = p; }
            } else if (std::abs(lk) < 0.12f) {
                float ec = edgeMinClearance(mid, p, true);
                if (ec > best_out_c) { best_out_c = ec; best_out = p; }
            }
        }
        if (best_in_c >= 0.0045f && best_out_c >= 0.0045f) {
            float mc = std::min({keyholes[i].clearance, best_in_c, best_out_c});
            #pragma omp critical
            bridges.push_back({best_in, mid, best_out, mc});
        }
    }

    std::sort(bridges.begin(), bridges.end(), [](const Bridge& a, const Bridge& b){
        return a.min_clear > b.min_clear;
    });
    std::cout << "Found " << bridges.size() << " clean bridges (>=4.5mm)!\n";
    for (size_t i = 0; i < std::min((size_t)8, bridges.size()); ++i) {
        std::cout << "  Bridge[" << i << "]: min_clear=" << bridges[i].min_clear
                  << " m, Lk_in=" << computeLinkingNumber(bridges[i].in_pose)
                  << ", Lk_out=" << computeLinkingNumber(bridges[i].out_pose) << "\n";
    }
    if (bridges.empty()) return 2;

    float best_bc = bridges[0].min_clear;
    float rrt_margin = std::max(0.005f, best_bc - 0.001f);
    std::vector<Pose> in_goals;
    for (size_t i = 0; i < std::min((size_t)10, bridges.size()); ++i) {
        if (bridges[i].min_clear >= rrt_margin) in_goals.push_back(bridges[i].in_pose);
    }
    if (in_goals.empty()) { in_goals.push_back(bridges[0].in_pose); rrt_margin = bridges[0].min_clear - 0.0005f; }

    std::cout << "Connecting start -> top bridges with margin=" << rrt_margin << " m...\n";
    std::vector<Pose> path1;
    bool ok1 = false;
    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        std::vector<Pose> lp;
        if (biRRTConnect(start_pose, in_goals, rrt_margin, 30000, 3000 + tid * 131, lp)) {
            #pragma omp critical
            if (!ok1 || lp.size() < path1.size()) { ok1 = true; path1 = lp; }
        }
    }
    if (!ok1) {
        // Fallback slightly lower margin if inside entrance is tighter
        rrt_margin = 0.0045f;
        std::cout << "Retrying with margin=" << rrt_margin << " m...\n";
        #pragma omp parallel num_threads(10)
        {
            int tid = omp_get_thread_num();
            std::vector<Pose> lp;
            if (biRRTConnect(start_pose, in_goals, rrt_margin, 30000, 4000 + tid * 131, lp)) {
                #pragma omp critical
                if (!ok1 || lp.size() < path1.size()) { ok1 = true; path1 = lp; }
            }
        }
    }
    if (!ok1) return 3;

    int chosen_b = 0; float bd = 1e30f;
    for (size_t i = 0; i < bridges.size(); ++i) {
        float d = poseMetric(path1.back(), bridges[i].in_pose);
        if (d < bd) { bd = d; chosen_b = (int)i; }
    }
    std::cout << "Connected start -> Bridge[" << chosen_b << "] (bridge_clear=" << bridges[chosen_b].min_clear << " m)\n";

    std::vector<Pose> esc_goals;
    std::vector<Vec3> gps = {
        Vec3(2.3f, -0.3f, 0.5f), Vec3(-0.3f, 1.4f, 0.5f),
        Vec3(1.2f, 2.1f, 0.5f),  Vec3(1.2f, -0.5f, 0.7f),
        Vec3(1.0f, 0.6f, 1.2f),  Vec3(2.2f, 1.6f, 0.6f),
        Vec3(0.2f, -0.4f, 0.6f), Vec3(1.8f, 0.2f, 0.9f)
    };
    for (const auto& gp : gps) {
        Pose ep{gp, bridges[chosen_b].out_pose.q};
        if (checkClearance(ep, 0.05f, true) >= 0.05f && canEscapeAlongRay(ep, 0.03f)) esc_goals.push_back(ep);
    }

    std::vector<Pose> path2;
    bool ok2 = false;
    #pragma omp parallel num_threads(10)
    {
        int tid = omp_get_thread_num();
        std::vector<Pose> lp;
        if (biRRTConnect(bridges[chosen_b].out_pose, esc_goals, rrt_margin, 30000, 7000 + tid * 131, lp)) {
            #pragma omp critical
            if (!ok2 || lp.size() < path2.size()) { ok2 = true; path2 = lp; }
        }
    }
    if (!ok2) return 4;

    std::vector<Pose> path = path1;
    path.push_back(bridges[chosen_b].mid_pose);
    path.insert(path.end(), path2.begin(), path2.end());

    // Truncate at earliest waypoint with generous 25mm ray escape + 0.08m step along escape ray!
    Vec3 esc_dir(0,0,1);
    for (size_t i = 1; i < path.size(); ++i) {
        Vec3 u;
        if (canEscapeAlongRay(path[i], 0.025f, &u)) {
            path.resize(i + 1);
            esc_dir = u;
            std::cout << "Truncated at waypoint " << i << " with 25mm escape ray!\n";
            break;
        }
    }
    Pose extra = path.back();
    extra.p = extra.p + esc_dir * 0.085f;
    if (edgeValid(path.back(), extra, rrt_margin, true, true) && canEscapeAlongRay(extra, 0.030f)) {
        path.push_back(extra);
    }

    auto subdivide = [&](const std::vector<Pose>& in, float max_p, float max_q) {
        std::vector<Pose> out;
        out.push_back(in[0]);
        for (size_t i = 0; i + 1 < in.size(); ++i) {
            float dp = (in[i+1].p - in[i].p).norm();
            float dq = quatAngleDist(in[i].q, in[i+1].q);
            int k = std::max(1, (int)std::ceil(std::max(dp / max_p, dq / max_q)));
            for (int s = 1; s <= k; ++s) {
                float t = (float)s / k;
                out.push_back({in[i].p + (in[i+1].p - in[i].p)*t, quatSlerp(in[i].q, in[i+1].q, t)});
            }
        }
        return out;
    };

    path = subdivide(path, 0.020f, 0.035f);

    // Fine-point Maximin-Clearance Path Optimization!
    for (int pass = 0; pass < 25; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            float old_e = std::min(edgeMinClearance(path[i-1], path[i], true),
                                   edgeMinClearance(path[i], path[i+1], true));
            Pose cand = path[i];
            if (pass % 2 == 0) {
                cand.p = (path[i-1].p + path[i].p * 2.0f + path[i+1].p) * 0.25f;
                cand.q = quatSlerp(quatSlerp(path[i-1].q, path[i+1].q, 0.5f), path[i].q, 0.5f);
            }
            retractPose(cand, std::min(0.025f, old_e + 0.008f), 3, true);
            float new_e = std::min(edgeMinClearance(path[i-1], cand, true),
                                   edgeMinClearance(cand, path[i+1], true));
            if (new_e > old_e || (old_e > 0.015f && new_e > 0.015f)) {
                path[i] = cand;
            }
        }
    }

    float bottle = 1e30f;
    for (size_t i = 0; i + 1 < path.size(); ++i) {
        bottle = std::min(bottle, edgeMinClearance(path[i], path[i+1], true));
    }
    std::cout << "Bottleneck clearance after fine medial-axis optimization: " << bottle << " m\n";

    // Strict safety margin for shortcutting & DP: keep within 0.4mm of true medial-axis bottleneck!
    float safe_m = std::min(0.014f, bottle - 0.0005f);
    std::cout << "Shortcutting & DP discretizing with strict BOTH-PROFILE margin = " << safe_m << " m...\n";

    std::mt19937 srng(42);
    for (int sc = 0; sc < 3000 && path.size() > 3; ++sc) {
        int i = srng() % (path.size() - 2);
        int j = i + 2 + (srng() % (path.size() - i - 2));
        if (edgeValid(path[i], path[j], safe_m, true, true)) {
            auto seg = subdivide({path[i], path[j]}, 0.018f, 0.030f);
            std::vector<Pose> next;
            next.insert(next.end(), path.begin(), path.begin() + i);
            next.insert(next.end(), seg.begin(), seg.end());
            next.insert(next.end(), path.begin() + j + 1, path.end());
            path.swap(next);
        }
    }

    // Re-polish clearance once more!
    for (int pass = 0; pass < 10; ++pass) {
        for (size_t i = 1; i + 1 < path.size(); ++i) {
            float old_e = std::min(edgeMinClearance(path[i-1], path[i], true),
                                   edgeMinClearance(path[i], path[i+1], true));
            Pose cand = path[i];
            retractPose(cand, std::min(0.025f, old_e + 0.006f), 2, true);
            float new_e = std::min(edgeMinClearance(path[i-1], cand, true),
                                   edgeMinClearance(cand, path[i+1], true));
            if (new_e > old_e) path[i] = cand;
        }
    }

    bottle = 1e30f;
    for (size_t i = 0; i + 1 < path.size(); ++i) bottle = std::min(bottle, edgeMinClearance(path[i], path[i+1], true));
    safe_m = std::min(0.014f, bottle - 0.0004f);

    // Shortest-path DAG for minimum move actions (<= 0.096 m, <= 0.192 rad)
    // Using exact `edgeMinClearance >= safe_m` across BOTH sync and indep profiles!
    int N = (int)path.size();
    std::vector<int> dp_cost(N, 1e9), dp_prev(N, -1);
    dp_cost[0] = 0;
    for (int i = 0; i < N; ++i) {
        if (dp_cost[i] >= 1e8) continue;
        for (int j = i + 1; j < N; ++j) {
            float dl = (path[j].p - path[i].p).norm();
            float da = quatAngleDist(path[i].q, path[j].q);
            if (dl > 0.096f || da > 0.192f) {
                if (dl > 0.16f || da > 0.32f) break;
                continue;
            }
            if (dp_cost[i] + 1 < dp_cost[j]) {
                if (edgeValid(path[i], path[j], safe_m, true, true) &&
                    edgeMinClearance(path[i], path[j], true) >= safe_m) {
                    dp_cost[j] = dp_cost[i] + 1;
                    dp_prev[j] = i;
                }
            }
        }
    }

    std::vector<Pose> actions;
    for (int c = N - 1; c != -1; c = dp_prev[c]) actions.push_back(path[c]);
    std::reverse(actions.begin(), actions.end());

    float min_sync = 1e30f, min_indep = 1e30f;
    for (size_t i = 0; i + 1 < actions.size(); ++i) {
        float dl = (actions[i+1].p - actions[i].p).norm();
        float da = quatAngleDist(actions[i].q, actions[i+1].q);
        for (int s = 0; s <= 40; ++s) {
            float t = s / 40.0f;
            Pose ms{actions[i].p + (actions[i+1].p - actions[i].p)*t, quatSlerp(actions[i].q, actions[i+1].q, t)};
            min_sync = std::min(min_sync, checkClearance(ms, -1.0f, true));
            if (dl > 1e-5f && da > 1e-5f) {
                float tl = dl / 0.1f, ta = da / 0.1f, tt = std::max(tl, ta);
                float tau = t * tt;
                Pose mi{actions[i].p + (actions[i+1].p - actions[i].p)*std::min(1.0f, tau/tl),
                        quatSlerp(actions[i].q, actions[i+1].q, std::min(1.0f, tau/ta))};
                min_indep = std::min(min_indep, checkClearance(mi, -1.0f, true));
            } else {
                min_indep = std::min(min_indep, checkClearance(ms, -1.0f, true));
            }
        }
    }

    std::cout << "\n========================================\n";
    std::cout << "HIGH-CLEARANCE OPTIMAL SOLUTION!\n";
    std::cout << "Move actions:       " << (actions.size() - 1) << " (+1 grab = " << actions.size() << " / 198)\n";
    std::cout << "Expected score:     " << (1.0 - 0.5 * actions.size() / 198.0) << "\n";
    std::cout << "Min clearance (sync):  " << min_sync << " m\n";
    std::cout << "Min clearance (indep): " << min_indep << " m\n";
    Vec3 fdir;
    bool fok = canEscapeAlongRay(actions.back(), 0.025f, &fdir);
    std::cout << "Final escape valid (25mm): " << fok << " along (" << fdir.x << "," << fdir.y << "," << fdir.z << ")\n";
    std::cout << "========================================\n";

    std::ofstream out("/app/planned_path.txt");
    out.precision(8);
    for (const auto& a : actions) {
        out << a.p.x << " " << a.p.y << " " << a.p.z << " "
            << a.q.w << " " << a.q.x << " " << a.q.y << " " << a.q.z << "\n";
    }
    return 0;
}

